    SlotRef stateSlotRef = new SlotRef(null, "state");
    StringLiteral stateStringLiteral = new StringLiteral("PENDING");
    BinaryPredicate stateEqPredicate = new BinaryPredicate(BinaryPredicate.Operator.EQ, stateSlotRef, stateStringLiteral);
