" + "SELECT CASE
" + "           WHEN
" + "                  (SELECT count(*)+abs(8)
" + "                   FROM db1.table1
" + "                   WHERE username='helen')>1 THEN 888
" + "           ELSE 999
" + "       END AS ccc
" + "FROM
" + "  (SELECT curdate()) a " + "ORDER BY curdate();";
