        // CHECKSTYLE IGNORE THIS LINE
        SelectStmt stmt = (SelectStmt) UtFrameUtils.parseAndAnalyzeStmt(sql, ctx);
    } catch (Exception e) {
        Assert.fail(e.getMessage());
    }
}

@Test
public void testSystemViewCaseInsensitive() throws Exception {
    String sql1 = "SELECT /*+ SET_VAR(enable_nereids_planner=false) */ ROUTINE_SCHEMA, ROUTINE_NAME FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA = " + "'ech_dw' ORDER BY ROUTINES.ROUTINE_SCHEMA\n";
    // The system view names in information_schema are case-insensitive,
    dorisAssert.query(sql1).explainQuery();
    String sql2 = "SELECT /*+ SET_VAR(enable_nereids_planner=false) */ ROUTINE_SCHEMA, ROUTINE_NAME FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA = " + "'ech_dw' ORDER BY routines.ROUTINE_SCHEMA\n";
    try {
        // Should not refer to one of system views using different cases within the same statement.
        // sql2 is wrong because 'ROUTINES' and 'routines' are used.
        dorisAssert.query(sql2).explainQuery();
        Assert.fail("Refer to one of system views using different cases within the same statement is wrong.");
    } catch (AnalysisException e) {
        System.out.println(e.getMessage());
    }
}

@Test
public void testWithUnionToSql() throws Exception {
    ConnectContext ctx = UtFrameUtils.createDefaultCtx();
    String sql1 = "select 
" + "  t.k1 
" + "from (
" + "  with 
" + "    v1 as (select t1.k1 from db1.tbl1 t1),
" + "    v2 as (select t2.k1 from db1.tbl1 t2)
" + "  select v1.k1 as k1 from v1
" + "  union
" + "  select v2.k1 as k1 from v2
" + ") t";
    SelectStmt stmt1 = (SelectStmt) UtFrameUtils.parseAndAnalyzeStmt(sql1, ctx);
    stmt1.rewriteExprs(new Analyzer(ctx.getEnv(), ctx).getExprRewriter());
    Assert.assertEquals("SELECT `t`.`k1` AS `k1` FROM (WITH v1 AS (SELECT `t1`.`k1` " + "FROM `db1`.`tbl1` t1),v2 AS (SELECT `t2`.`k1` FROM `db1`.`tbl1` t2) " + "SELECT `v1`.`k1` AS `k1` FROM `v1` UNION SELECT `v2`.`k1` AS `k1` FROM `v2`) t", stmt1.toSql());
    String sql2 = "with
" + "    v1 as (select t1.k1 from db1.tbl1 t1),
" + "    v2 as (select t2.k1 from db1.tbl1 t2)
" + "select
" + "  t.k1
" + "from (
" + "  select v1.k1 as k1 from v1
" + "  union
" + "  select v2.k1 as k1 from v2
" + ") t";
    SelectStmt stmt2 = (SelectStmt) UtFrameUtils.parseAndAnalyzeStmt(sql2, ctx);
    stmt2.rewriteExprs(new Analyzer(ctx.getEnv(), ctx).getExprRewriter());
    Assert.assertTrue(stmt2.toSql().contains("WITH v1 AS (SELECT `t1`.`k1` FROM `db1`.`tbl1` t1)," + "v2 AS (SELECT `t2`.`k1` FROM `db1`.`tbl1` t2)"));
}

