    stmtExecutor.execute();
    Assert.assertEquals("STRICT_TRANS_TABLES", SqlModeHelper.decode(connectContext.getSessionVariable().getSqlMode()));
    String selectStr = "explain select /*+ SET_VAR(enable_nereids_planner=false) */ @@sql_mode;";
