    new MockUp<CatalogMgr>() {

        @Mock
        public CatalogIf getCatalog(String name) {
            switch(name) {
                case "hms":
                    return hmsExternalCatalog;
                case "ice":
                    return icebergExternalCatalog;
                default:
                    return null;
            }
        }
    };
    AtomicBoolean isView = new AtomicBoolean(true);
    AtomicBoolean isPartitioned = new AtomicBoolean(false);
    new Expectations() {

        {
            hmsExternalCatalog.getDbNullable(anyString);
            result = new Delegate<DatabaseIf>() {

                DatabaseIf catalogResult(String name) {
                    switch(name) {
                        case "hms":
                            return hmsExternalDatabase;
                        default:
                            return null;
                    }
                }
            };
            hmsExternalTable.isView();
            result = new Delegate<Boolean>() {

                boolean isView() {
                    return isView.get();
                }
            };
            hmsExternalTable.getPartitionColumns();
            result = new Delegate<List>() {

                List<Column> data() {
                    if (isPartitioned.get()) {
                        return Arrays.asList(new Column("test", PrimitiveType.INT));
                    }
                    return Arrays.asList();
                }
            };
        }
    };
    SlotRef slotRef = new SlotRef(null, "PartitionName");
    StringLiteral stringLiteral = new StringLiteral("part=part1");
    BinaryPredicate binaryPredicate = new BinaryPredicate(BinaryPredicate.Operator.EQ, slotRef, stringLiteral);
    /* case 0: Catalog - iceberg */
    {
        ShowPartitionsStmt stmt = new ShowPartitionsStmt(new TableName("ice", "null", "testTable"), binaryPredicate, null, null, false);
        Assertions.assertThrows(AnalysisException.class, () -> stmt.analyze(analyzer));
    }
    /* case 1: Catalog - null */
    {
        ShowPartitionsStmt stmt = new ShowPartitionsStmt(new TableName("null", "null", "testTable"), binaryPredicate, null, null, false);
        Assertions.assertThrows(AnalysisException.class, () -> stmt.analyze(analyzer));
    }
    /* case 2: HMSExternalTable null */
    {
        ShowPartitionsStmt stmt = new ShowPartitionsStmt(new TableName("hms", "null", "testTable"), binaryPredicate, null, null, false);
        Assertions.assertThrows(AnalysisException.class, () -> stmt.analyze(analyzer));
    }
    /* case 3: HMSExternalTable : isView */
    {
        ShowPartitionsStmt stmt = new ShowPartitionsStmt(new TableName("hms", "hms", "testTable"), binaryPredicate, null, null, false);
        Assertions.assertThrows(AnalysisException.class, () -> stmt.analyze(analyzer));
        isView.set(false);
    }
    /* case 4: HMSExternalTable : notPartitioned */
    {
        ShowPartitionsStmt stmt = new ShowPartitionsStmt(new TableName("hms", "hms", "testTable"), binaryPredicate, null, null, false);
        Assertions.assertThrows(AnalysisException.class, () -> stmt.analyze(analyzer));
    }
    /* case 5: HMSExternalTable : partitioned */
    {
        isPartitioned.set(true);
        ShowPartitionsStmt stmt = new ShowPartitionsStmt(new TableName("hms", "hms", "testTable"), binaryPredicate, null, null, false);
        Assertions.assertEquals(stmt.toSql(), "SHOW PARTITIONS FROM `hms`.`testTable` " + "WHERE (`PartitionName` = 'part=part1')");
    }
}

@Test
public void testShowReplicaDistribution() throws Exception {
    String stmtStr = "show replica distribution from test.tbl1 partition(p1)";
    ShowReplicaDistributionStmt stmt = (ShowReplicaDistributionStmt) parseAndAnalyzeStmt(stmtStr);
    ShowExecutor executor = new ShowExecutor(connectContext, stmt);
    ShowResultSet resultSet = executor.execute();
    Assert.assertEquals(1, resultSet.getResultRows().size());
    Assert.assertEquals(9, resultSet.getResultRows().get(0).size());
    stmtStr = "show data skew from test.tbl1 partition(p1)";
    ShowDataSkewStmt skewStmt = (ShowDataSkewStmt) parseAndAnalyzeStmt(stmtStr);
    executor = new ShowExecutor(connectContext, skewStmt);
    resultSet = executor.execute();
    Assert.assertEquals(10, resultSet.getResultRows().size());
    Assert.assertEquals(6, resultSet.getResultRows().get(0).size());
    // update tablets' data size and row count
    Database db = Env.getCurrentInternalCatalog().getDbOrAnalysisException("test");
    OlapTable olapTable = db.getOlapTableOrAnalysisException("tbl1");
    for (Partition partition : olapTable.getPartitions()) {
        for (MaterializedIndex index : partition.getMaterializedIndices(MaterializedIndex.IndexExtState.VISIBLE)) {
            for (Tablet tablet : index.getTablets()) {
                for (Replica replica : tablet.getReplicas()) {
                    replica.setDataSize(1024L);
                    replica.setRowCount(2L);
                }
            }
        }
    }
    executor = new ShowExecutor(connectContext, stmt);
    resultSet = executor.execute();
    Assert.assertEquals(1, resultSet.getResultRows().size());
    Assert.assertEquals(9, resultSet.getResultRows().get(0).size());
    executor = new ShowExecutor(connectContext, skewStmt);
    resultSet = executor.execute();
    Assert.assertEquals(10, resultSet.getResultRows().size());
    Assert.assertEquals("4", resultSet.getResultRows().get(4).get(1));
    Assert.assertEquals(6, resultSet.getResultRows().get(0).size());
}

