    String sql = "create stage ex_stage_1 " + "PROPERTIES ('endpoint' = 'cos.ap-beijing.myqcloud.com', " + "'region' = 'ap-beijing', " + "'prefix' = 'tmp_prefix', " + "'ak'='tmp_ak', 'sk'='tmp_sk', 'access_type'='aksk');";
