    String table2 = "create table db1.TABle2(k1 int, k2 varchar(32), k3 varchar(32)) " + "AGGREGATE KEY(k1, k2, k3) distributed by hash(k1) buckets 3 properties('replication_num' = '1');";
    try {
        dorisAssert.withTable(table2);
        Assert.fail("The table name is case insensitive, " + "but the tables 'TABLE2' and 'table2' were successfully created");
    } catch (Exception e) {
        System.out.println(e.getMessage());
    }
    String view2 = "create view table2 as select * from TABLE2";
    try {
        dorisAssert.withView(view2);
        Assert.fail("The table name is case insensitive, " + "but the table 'TABLE2' and view 'table2' were successfully created");
    } catch (Exception e) {
        System.out.println(e.getMessage());
    }
}

