@Test
public void testSerialization() throws IOException, AnalysisException {
    // 1. Write objects to file
    final Path path = Files.createTempFile("backupJob", "tmp");
    DataOutputStream out = new DataOutputStream(Files.newOutputStream(path));
    List<TableRef> tableRefs = Lists.newArrayList();
    tableRefs.add(new TableRef(new TableName(InternalCatalog.INTERNAL_CATALOG_NAME, UnitTestUtil.DB_NAME, UnitTestUtil.TABLE_NAME), null));
