    out.flush();
    out.close();
    // 2. Read objects from file
    DataInputStream in = new DataInputStream(Files.newInputStream(path));
    BackupJob job2 = BackupJob.read(in);
    Assert.assertEquals(job.getJobId(), job2.getJobId());
