@Test
public void testFillHistoryDynamicPartition3() throws Exception {
    String createOlapTblStmt = "CREATE TABLE test.`dynamic_partition3` (
" + "  `k1` date NULL COMMENT ""
" + ")
" + "PARTITION BY RANGE (k1)
" + "()
" + "DISTRIBUTED BY HASH(`k1`) BUCKETS 1
