@Test
public void testRecover() throws Exception {
    createDb("test");
    createTable("CREATE TABLE test.`table1` (
" + "  `event_date` date NOT NULL COMMENT "",
" + "  `app_name` varchar(64) NOT NULL COMMENT "",
" + "  `package_name` varchar(64) NOT NULL COMMENT "",
" + "  `age` varchar(32) NOT NULL COMMENT "",
" + "  `gender` varchar(32) NOT NULL COMMENT "",
" + "  `level` varchar(64) NOT NULL COMMENT "",
" + "  `city` varchar(64) NOT NULL COMMENT "",
" + "  `model` varchar(64) NOT NULL COMMENT "",
" + "  `brand` varchar(64) NOT NULL COMMENT "",
" + "  `hours` varchar(16) NOT NULL COMMENT "",
" + "  `use_num` int(11) SUM NOT NULL COMMENT "",
" + "  `use_time` double SUM NOT NULL COMMENT "",
" + "  `start_times` bigint(20) SUM NOT NULL COMMENT ""
" + ") ENGINE=OLAP
" + "AGGREGATE KEY(`event_date`, `app_name`, `package_name`, `age`, `gender`, `level`, `city`, 
" + " `model`, `brand`, `hours`) COMMENT "OLAP"
" + "PARTITION BY RANGE(`event_date`)
" + "(PARTITION p1 VALUES [('2020-02-27'), ('2020-03-02')),
" + "PARTITION p2 VALUES [('2020-03-02'), ('2020-03-07')))
" + "DISTRIBUTED BY HASH(`event_date`, `app_name`, `package_name`, `age`, `gender`, `level`, `city`, 
" + " `model`, `brand`, `hours`) BUCKETS 1 PROPERTIES (
" + " "replication_num" = "1"
" + ");");
    Assert.assertTrue(checkDbExist("test"));
    Assert.assertTrue(checkTableExist("test", "table1"));
    dropDb("test");
    Assert.assertFalse(checkDbExist("test"));
    Assert.assertFalse(checkTableExist("test", "table1"));
    recoverDb("test", -1);
    Assert.assertTrue(checkDbExist("test"));
    Assert.assertTrue(checkTableExist("test", "table1"));
    long dbId = getDbId("test");
    dropDb("test");
    Assert.assertFalse(checkDbExist("test"));
    Assert.assertFalse(checkTableExist("test", "table1"));
    recoverDb("test", dbId);
    Assert.assertTrue(checkDbExist("test"));
    Assert.assertTrue(checkTableExist("test", "table1"));
    dropTable("test", "table1");
    Assert.assertTrue(checkDbExist("test"));
    Assert.assertFalse(checkTableExist("test", "table1"));
    recoverTable("test", "table1", -1);
    Assert.assertTrue(checkDbExist("test"));
    Assert.assertTrue(checkTableExist("test", "table1"));
    dropTable("test", "table1");
    Assert.assertTrue(checkDbExist("test"));
    Assert.assertFalse(checkTableExist("test", "table1"));
    createTable("CREATE TABLE test.`table1` (
" + "  `event_date` date NOT NULL COMMENT "",
" + "  `app_name` varchar(64) NOT NULL COMMENT "",
" + "  `package_name` varchar(64) NOT NULL COMMENT "",
" + "  `age` varchar(32) NOT NULL COMMENT "",
" + "  `gender` varchar(32) NOT NULL COMMENT "",
" + "  `level` varchar(64) NOT NULL COMMENT "",
" + "  `city` varchar(64) NOT NULL COMMENT "",
" + "  `model` varchar(64) NOT NULL COMMENT "",
" + "  `brand` varchar(64) NOT NULL COMMENT "",
" + "  `hours` varchar(16) NOT NULL COMMENT "",
" + "  `use_num` int(11) SUM NOT NULL COMMENT "",
" + "  `use_time` double SUM NOT NULL COMMENT "",
" + "  `start_times` bigint(20) SUM NOT NULL COMMENT ""
" + ") ENGINE=OLAP
" + "AGGREGATE KEY(`event_date`, `app_name`, `package_name`, `age`, `gender`, `level`, 
" + " `city`, `model`, `brand`, `hours`) COMMENT "OLAP"
" + "PARTITION BY RANGE(`event_date`)
" + "(PARTITION p1 VALUES [('2020-02-27'), ('2020-03-02')),
" + "PARTITION p2 VALUES [('2020-03-02'), ('2020-03-07')))
" + "DISTRIBUTED BY HASH(`event_date`, `app_name`, `package_name`, `age`, `gender`, `level`, `city`, 
" + " `model`, `brand`, `hours`) BUCKETS 1 PROPERTIES (
" + " "replication_num" = "1"
" + ");");
    Assert.assertTrue(checkDbExist("test"));
    Assert.assertTrue(checkTableExist("test", "table1"));
    try {
        recoverTable("test", "table1", -1);
        Assert.fail("should not recover succeed");
    } catch (DdlException e) {
        e.printStackTrace();
    }
    Assert.assertTrue(checkPartitionExist("test", "table1", "p1"));
    dropPartition("test", "table1", "p1");
    Assert.assertFalse(checkPartitionExist("test", "table1", "p1"));
    recoverPartition("test", "table1", "p1", -1);
    Assert.assertTrue(checkPartitionExist("test", "table1", "p1"));
}

