@Test
public void testGlobalColocateStatistic() {
    GroupId groupId1 = new GroupId(1L, 10000L);
    GroupId groupId2 = new GroupId(2L, 20000L);
    GlobalColocateStatistic globalColocateStatistic = new GlobalColocateStatistic();
    globalColocateStatistic.addGroup(groupId1, new ReplicaAllocation((short) 2), Lists.newArrayList(Sets.newHashSet(1001L, 1002L), Sets.newHashSet(1002L, 1003L), Sets.newHashSet(1001L, 1003L)), Lists.newArrayList(100L, 200L, 300L), 5);
    globalColocateStatistic.addGroup(groupId2, new ReplicaAllocation((short) 1), Lists.newArrayList(Sets.newHashSet(1001L), Sets.newHashSet(1002L), Sets.newHashSet(1003L), Sets.newHashSet(1001L)), Lists.newArrayList(100L, 200L, 300L, 400L), 7);
    Map<Long, BackendBuckets> backendBucketsMap = globalColocateStatistic.getBackendBucketsMap();
    BackendBuckets backendBuckets1 = backendBucketsMap.get(1001L);
    Assert.assertNotNull(backendBuckets1);
    Assert.assertEquals(Lists.newArrayList(0, 2), backendBuckets1.getGroupTabletOrderIndices().get(groupId1));
    Assert.assertEquals(Lists.newArrayList(0, 3), backendBuckets1.getGroupTabletOrderIndices().get(groupId2));
    BackendBuckets backendBuckets2 = backendBucketsMap.get(1002L);
    Assert.assertNotNull(backendBuckets2);
    Assert.assertEquals(Lists.newArrayList(0, 1), backendBuckets2.getGroupTabletOrderIndices().get(groupId1));
    Assert.assertEquals(Lists.newArrayList(1), backendBuckets2.getGroupTabletOrderIndices().get(groupId2));
    BackendBuckets backendBuckets3 = backendBucketsMap.get(1003L);
    Assert.assertNotNull(backendBuckets3);
    Assert.assertEquals(Lists.newArrayList(1, 2), backendBuckets3.getGroupTabletOrderIndices().get(groupId1));
    Assert.assertEquals(Lists.newArrayList(2), backendBuckets3.getGroupTabletOrderIndices().get(groupId2));
    Map<GroupId, List<BucketStatistic>> allGroupBucketsMap = globalColocateStatistic.getAllGroupBucketsMap();
    Assert.assertEquals(Lists.newArrayList(new BucketStatistic(0, 5, 100L), new BucketStatistic(1, 5, 200L), new BucketStatistic(2, 5, 300L)), allGroupBucketsMap.get(groupId1));
    Assert.assertEquals(Lists.newArrayList(new BucketStatistic(0, 7, 100L), new BucketStatistic(1, 7, 200L), new BucketStatistic(2, 7, 300L), new BucketStatistic(3, 7, 400L)), allGroupBucketsMap.get(groupId2));
    Map<Tag, Integer> expectAllTagBucketNum = Maps.newHashMap();
    expectAllTagBucketNum.put(Tag.DEFAULT_BACKEND_TAG, 10);
    Assert.assertEquals(expectAllTagBucketNum, globalColocateStatistic.getAllTagBucketNum());
}

