@Test
public void testDiskReblanceWhenSchedulerIdle() throws Exception {
    // case start
    TabletInvertedIndex invertedIndex = Env.getCurrentInvertedIndex();
    List<Backend> backends = Env.getCurrentSystemInfo().getAllBackends();
    Assertions.assertEquals(backendNum(), backends.size());
    for (Backend be : backends) {
        Assertions.assertEquals(0, invertedIndex.getTabletNumByBackendId(be.getId()));
    }
    long totalCapacity = 10L << 30;
    for (int i = 0; i < backends.size(); i++) {
        Map<String, DiskInfo> disks = Maps.newHashMap();
        for (int j = 0; j < 2; j++) {
            DiskInfo diskInfo = new DiskInfo("be_" + i + "_disk_" + j);
            diskInfo.setTotalCapacityB(totalCapacity);
            diskInfo.setDataUsedCapacityB(1L << 30);
            diskInfo.setAvailableCapacityB(9L << 30);
            diskInfo.setPathHash((1000L * (i + 1)) + 10 * j);
            disks.put(diskInfo.getRootPath(), diskInfo);
        }
        backends.get(i).setDisks(ImmutableMap.copyOf(disks));
    }
    Backend be0 = backends.get(0);
    createDatabase("test");
    createTable("CREATE TABLE test.tbl1 (k INT) DISTRIBUTED BY HASH(k) " + " BUCKETS 4 PROPERTIES ( \"replication_num\" = \"1\"," + " \"storage_medium\" = \"HDD\")");
    Assertions.assertEquals(2, invertedIndex.getTabletNumByBackendId(backends.get(0).getId()));
    Assertions.assertEquals(2, invertedIndex.getTabletNumByBackendId(backends.get(1).getId()));
    Database db = Env.getCurrentInternalCatalog().getDbOrMetaException("test");
    OlapTable tbl = (OlapTable) db.getTableOrMetaException("tbl1");
    Assertions.assertNotNull(tbl);
    Partition partition = tbl.getPartitions().iterator().next();
    List<Tablet> tablets = partition.getMaterializedIndices(MaterializedIndex.IndexExtState.ALL).iterator().next().getTablets();
    DiskInfo diskInfo0 = be0.getDisks().values().asList().get(0);
    DiskInfo diskInfo1 = be0.getDisks().values().asList().get(1);
    tablets.forEach(tablet -> {
        Lists.newArrayList(tablet.getReplicas()).forEach(replica -> {
            if (replica.getBackendId() == backends.get(1).getId()) {
                replica.setDataSize(totalCapacity / 4);
                replica.setRowCount(1);
                tablet.deleteReplica(replica);
                replica.setBackendId(backends.get(0).getId());
                replica.setPathHash(diskInfo0.getPathHash());
                tablet.addReplica(replica);
            } else {
                replica.setPathHash(diskInfo0.getPathHash());
            }
        });
    });
    diskInfo0.setAvailableCapacityB(0L);
    diskInfo1.setAvailableCapacityB(totalCapacity);
    DebugPointUtil.addDebugPointWithValue("FE.HIGH_LOAD_BE_ID", backends.get(1).getId());
    Table<Tag, TStorageMedium, Long> lastPickTimeTable = Env.getCurrentEnv().getTabletScheduler().getRebalancer().getLastPickTimeTable();
    lastPickTimeTable.put(Tag.DEFAULT_BACKEND_TAG, TStorageMedium.HDD, 0L);
    Config.disable_balance = false;
    try {
        Thread.sleep(1000L);
    } catch (InterruptedException e) {
        throw new RuntimeException(e);
    }
    Map<Long, Integer> gotDiskTabletNums = Maps.newHashMap();
    tablets.forEach(tablet -> tablet.getReplicas().forEach(replica -> {
        gotDiskTabletNums.put(replica.getPathHash(), 1 + gotDiskTabletNums.getOrDefault(replica.getPathHash(), 0));
    }));
    Map<Long, Integer> expectTabletNums = Maps.newHashMap();
    expectTabletNums.put(diskInfo0.getPathHash(), 2);
    expectTabletNums.put(diskInfo1.getPathHash(), 2);
    Assertions.assertEquals(expectTabletNums, gotDiskTabletNums);
}

@Test
public void test() {
    Config.balance_slot_num_per_path = 2;
    Map<Long, TStorageMedium> paths = Maps.newHashMap();
    List<Long> availPathHashs = Lists.newArrayList();
    List<Long> expectPathHashs = Lists.newArrayList();
    List<Long> gotPathHashs = Lists.newArrayList();
    TStorageMedium medium = TStorageMedium.HDD;
    long startPath = 10001L;
    long endPath = 10006L;
    for (long pathHash = startPath; pathHash < endPath; pathHash++) {
        paths.put(pathHash, medium);
        availPathHashs.add(pathHash);
        expectPathHashs.add(pathHash);
    }
    for (long pathHash = startPath; pathHash < endPath; pathHash++) {
        expectPathHashs.add(pathHash);
    }
    for (long pathHash = startPath; pathHash < endPath; pathHash++) {
        expectPathHashs.add(-1L);
    }
    PathSlot ps = new PathSlot(paths, 1L);
    for (int i = 0; i < expectPathHashs.size(); i++) {
        Collections.shuffle(availPathHashs);
        gotPathHashs.add(ps.takeAnAvailBalanceSlotFrom(availPathHashs, medium));
    }
    Assert.assertEquals(expectPathHashs, gotPathHashs);
}

@Test
public void testPrioBackends() {
    Rebalancer rebalancer = new DiskRebalancer(Env.getCurrentSystemInfo(), Env.getCurrentInvertedIndex(), null);
    // add
    {
        // CHECKSTYLE IGNORE THIS LINE
        List<Backend> backends = Lists.newArrayList();
        for (int i = 0; i < 3; i++) {
            backends.add(RebalancerTestUtil.createBackend(10086 + i, 2048, 0));
        }
        rebalancer.addPrioBackends(backends, 1000);
        Assert.assertTrue(rebalancer.hasPrioBackends());
    }
    // CHECKSTYLE IGNORE THIS LINE
    // remove
    for (int i = 0; i < 3; i++) {
        List<Backend> backends = Lists.newArrayList(RebalancerTestUtil.createBackend(10086 + i, 2048, 0));
        rebalancer.removePrioBackends(backends);
        if (i == 2) {
            Assert.assertFalse(rebalancer.hasPrioBackends());
        } else {
            Assert.assertTrue(rebalancer.hasPrioBackends());
        }
    }
}

@Test
public void testPartitionRebalancer() {
    Configurator.setLevel("org.apache.doris.clone.PartitionRebalancer", Level.DEBUG);
    // Disable scheduler's rebalancer adding balance task, add balance tasks manually
    Config.disable_balance = true;
    // generate statistic map again to create skewmap
    Config.tablet_rebalancer_type = "partition";
    generateStatisticMap();
    // Create a new scheduler & checker for redundant tablets handling
    // Call runAfterCatalogReady manually instead of starting daemon thread
    TabletSchedulerStat stat = new TabletSchedulerStat();
    PartitionRebalancer rebalancer = new PartitionRebalancer(Env.getCurrentSystemInfo(), Env.getCurrentInvertedIndex(), null);
    TabletScheduler tabletScheduler = new TabletScheduler(env, systemInfoService, invertedIndex, stat, "");
    // The rebalancer inside the scheduler will use this rebalancer, for getToDeleteReplicaId
    Deencapsulation.setField(tabletScheduler, "rebalancer", rebalancer);
    TabletChecker tabletChecker = new TabletChecker(env, systemInfoService, tabletScheduler, stat);
    rebalancer.updateLoadStatistic(statisticMap);
    List<TabletSchedCtx> alternativeTablets = rebalancer.selectAlternativeTablets();
    // Run once for update slots info, scheduler won't select balance cuz balance is disabled
    tabletScheduler.runAfterCatalogReady();
    AgentBatchTask batchTask = new AgentBatchTask();
    for (TabletSchedCtx tabletCtx : alternativeTablets) {
        LOG.info("try to schedule tablet {}", tabletCtx.getTabletId());
        try {
            tabletCtx.setStorageMedium(TStorageMedium.HDD);
            tabletCtx.setTablet(olapTable.getPartition(tabletCtx.getPartitionId()).getIndex(tabletCtx.getIndexId()).getTablet(tabletCtx.getTabletId()));
            tabletCtx.setVersionInfo(1, 1);
            tabletCtx.setSchemaHash(olapTable.getSchemaHashByIndexId(tabletCtx.getIndexId()));
            // rebalance tablet should be healthy first
            tabletCtx.setTabletStatus(Tablet.TabletStatus.HEALTHY);
            // createCloneReplicaAndTask, create replica will change invertedIndex too.
            AgentTask task = rebalancer.createBalanceTask(tabletCtx);
            batchTask.addTask(task);
        } catch (SchedException e) {
            LOG.warn("schedule tablet {} failed: {}", tabletCtx.getTabletId(), e.getMessage());
        }
    }
    // Show debug info of MoveInProgressMap detail
    rebalancer.updateLoadStatistic(statisticMap);
    rebalancer.selectAlternativeTablets();
    // Get created tasks, and finish them manually
    List<AgentTask> tasks = batchTask.getAllTasks();
    List<Long> needCheckTablets = tasks.stream().map(AgentTask::getTabletId).collect(Collectors.toList());
    LOG.info("created tasks for tablet: {}", needCheckTablets);
    needCheckTablets.forEach(t -> Assert.assertEquals(4, invertedIndex.getReplicasByTabletId(t).size()));
    for (Long tabletId : needCheckTablets) {
        TabletSchedCtx tabletSchedCtx = alternativeTablets.stream().filter(ctx -> ctx.getTabletId() == tabletId).collect(MoreCollectors.onlyElement());
        AgentTask task = tasks.stream().filter(t -> t.getTabletId() == tabletId).collect(MoreCollectors.onlyElement());
        LOG.info("try to finish tabletCtx {}", tabletId);
        try {
            TFinishTaskRequest fakeReq = new TFinishTaskRequest();
            fakeReq.task_status = new TStatus(TStatusCode.OK);
            fakeReq.finish_tablet_infos = Lists.newArrayList(new TTabletInfo(tabletSchedCtx.getTabletId(), 5, 1, 0, 0, 0));
            tabletSchedCtx.finishCloneTask((CloneTask) task, fakeReq);
        } catch (SchedException e) {
            e.printStackTrace();
        }
    }
    // NeedCheckTablets are redundant, TabletChecker will add them to TabletScheduler
    tabletChecker.runAfterCatalogReady();
    needCheckTablets.forEach(t -> Assert.assertEquals(4, invertedIndex.getReplicasByTabletId(t).size()));
    needCheckTablets.forEach(t -> Assert.assertTrue(tabletScheduler.containsTablet(t)));
    // TabletScheduler handle redundant tablet
    tabletScheduler.runAfterCatalogReady();
    // One replica is set to DECOMMISSION, still 4 replicas
    needCheckTablets.forEach(t -> {
        List<Replica> replicas = invertedIndex.getReplicasByTabletId(t);
        Assert.assertEquals(4, replicas.size());
        Replica decommissionedReplica = replicas.stream().filter(r -> r.getState() == Replica.ReplicaState.DECOMMISSION).collect(MoreCollectors.onlyElement());
        Assert.assertEquals(111, decommissionedReplica.getPreWatermarkTxnId());
        Assert.assertEquals(112, decommissionedReplica.getPostWatermarkTxnId());
    });
    // Delete replica should change invertedIndex too
    tabletScheduler.runAfterCatalogReady();
    needCheckTablets.forEach(t -> Assert.assertEquals(3, invertedIndex.getReplicasByTabletId(t).size()));
    // Check moves completed
    rebalancer.selectAlternativeTablets();
    rebalancer.updateLoadStatistic(statisticMap);
    AtomicLong succeeded = Deencapsulation.getField(rebalancer, "counterBalanceMoveSucceeded");
    Assert.assertEquals(needCheckTablets.size(), succeeded.get());
}

@Test
public void testMoveInProgressMap() {
    Configurator.setLevel("org.apache.doris.clone.MovesInProgressCache", Level.DEBUG);
    MovesCacheMap m = new MovesCacheMap();
    m.updateMapping(statisticMap, 3);
    m.getCache(Tag.DEFAULT_BACKEND_TAG, TStorageMedium.HDD).get().put(1L, Pair.of(null, -1L));
    m.getCache(Tag.DEFAULT_BACKEND_TAG, TStorageMedium.SSD).get().put(2L, Pair.of(null, -1L));
    m.getCache(Tag.DEFAULT_BACKEND_TAG, TStorageMedium.SSD).get().put(3L, Pair.of(null, -1L));
    // Maintenance won't clean up the entries of cache
    m.maintain();
    Assert.assertEquals(3, m.size());
    // Reset the expireAfterAccess, the whole cache map will be cleared.
    m.updateMapping(statisticMap, 1);
    Assert.assertEquals(0, m.size());
    m.getCache(Tag.DEFAULT_BACKEND_TAG, TStorageMedium.SSD).get().put(3L, Pair.of(null, -1L));
    try {
        Thread.sleep(1000);
        m.maintain();
        Assert.assertEquals(0, m.size());
    } catch (InterruptedException e) {
        e.printStackTrace();
    }
}

@Test
public void testRepairLastFailedVersionByClone() throws Exception {
    TableInfo info = prepareTableForTest("tbl_repair_last_fail_version_by_clone");
    Partition partition = info.partition;
    Replica replica = info.replica;
    replica.updateLastFailedVersion(replica.getVersion() + 1);
    Assertions.assertEquals(partition.getCommittedVersion() + 1, replica.getLastFailedVersion());
    Config.disable_tablet_scheduler = false;
    Thread.sleep(1000);
    Config.disable_tablet_scheduler = true;
    Assertions.assertEquals(partition.getVisibleVersion(), replica.getVersion());
    Assertions.assertEquals(-1L, replica.getLastFailedVersion());
}

@Test
public void testRepairLastFailedVersionByReport() throws Exception {
    TableInfo info = prepareTableForTest("tbl_repair_last_fail_version_by_report");
    Partition partition = info.partition;
    Tablet tablet = info.tablet;
    Replica replica = info.replica;
    replica.updateLastFailedVersion(replica.getVersion() + 1);
    Assertions.assertEquals(partition.getCommittedVersion() + 1, replica.getLastFailedVersion());
    TTabletInfo tTabletInfo = new TTabletInfo();
    tTabletInfo.setTabletId(tablet.getId());
    tTabletInfo.setSchemaHash(replica.getSchemaHash());
    tTabletInfo.setVersion(replica.getVersion());
    tTabletInfo.setPathHash(replica.getPathHash());
    tTabletInfo.setPartitionId(partition.getId());
    tTabletInfo.setReplicaId(replica.getId());
    TTablet tTablet = new TTablet();
    tTablet.addToTabletInfos(tTabletInfo);
    Map<Long, TTablet> tablets = Maps.newHashMap();
    tablets.put(tablet.getId(), tTablet);
    Assertions.assertEquals(partition.getVisibleVersion(), replica.getVersion());
    ReportHandler.tabletReport(replica.getBackendId(), tablets, Maps.newHashMap(), 100L);
    Assertions.assertEquals(partition.getVisibleVersion(), replica.getVersion());
    Assertions.assertEquals(-1L, replica.getLastFailedVersion());
}

@Test
public void testVersionRegressive() throws Exception {
    TableInfo info = prepareTableForTest("tbl_version_regressive");
    Partition partition = info.partition;
    Tablet tablet = info.tablet;
    Replica replica = info.replica;
    Assertions.assertEquals(partition.getVisibleVersion(), replica.getVersion());
    Assertions.assertEquals(-1L, replica.getLastFailedVersion());
    Assertions.assertTrue(replica.getVersion() > 1L);
    TTabletInfo tTabletInfo = new TTabletInfo();
    tTabletInfo.setTabletId(tablet.getId());
    tTabletInfo.setSchemaHash(replica.getSchemaHash());
    // be report version = 1 which less than fe version
    tTabletInfo.setVersion(1L);
    tTabletInfo.setPathHash(replica.getPathHash());
    tTabletInfo.setPartitionId(partition.getId());
    tTabletInfo.setReplicaId(replica.getId());
    TTablet tTablet = new TTablet();
    tTablet.addToTabletInfos(tTabletInfo);
    Map<Long, TTablet> tablets = Maps.newHashMap();
    tablets.put(tablet.getId(), tTablet);
    ReportHandler.tabletReport(replica.getBackendId(), tablets, Maps.newHashMap(), 100L);
    Assertions.assertEquals(-1L, replica.getLastFailedVersion());
    DebugPointUtil.addDebugPoint("Replica.regressive_version_immediately", new DebugPoint());
    ReportHandler.tabletReport(replica.getBackendId(), tablets, Maps.newHashMap(), 100L);
    Assertions.assertEquals(replica.getVersion() + 1, replica.getLastFailedVersion());
    Assertions.assertEquals(partition.getVisibleVersion(), replica.getVersion());
}

@Test
public void test() {
    RootPathLoadStatistic usage1 = new RootPathLoadStatistic(0L, "/home/disk1", 12345L, TStorageMedium.HDD, 4096L, 1024L, DiskState.ONLINE);
    RootPathLoadStatistic usage2 = new RootPathLoadStatistic(0L, "/home/disk2", 67890L, TStorageMedium.HDD, 4096L, 2048L, DiskState.ONLINE);
    List<RootPathLoadStatistic> list = Lists.newArrayList();
    list.add(usage1);
    list.add(usage2);
    // low usage should be ahead
    Collections.sort(list);
    Assert.assertTrue(list.get(0).getPathHash() == usage1.getPathHash());
    usage1.incrCopingSizeB(2048L);
    Collections.sort(list);
    Assert.assertTrue(list.get(1).getPathHash() == usage1.getPathHash());
}

@Test
public void test() throws Exception {
    Assert.assertEquals(5, backends.size());
    // set tag for all backends. 0-2 to zone1, 4 and 5 to zone2
    for (int i = 0; i < backends.size(); ++i) {
        Backend be = backends.get(i);
        String tag = "zone1";
        if (i > 2) {
            tag = "zone2";
        }
        String stmtStr = "alter system modify backend \"" + be.getHost() + ":" + be.getHeartbeatPort() + "\" set ('tag.location' = '" + tag + "')";
        AlterSystemStmt stmt = (AlterSystemStmt) UtFrameUtils.parseAndAnalyzeStmt(stmtStr, connectContext);
        DdlExecutor.execute(Env.getCurrentEnv(), stmt);
    }
    // Test set tag without location type, expect throw exception
    Backend be1 = backends.get(0);
    String alterString = "alter system modify backend \"" + be1.getHost() + ":" + be1.getHeartbeatPort() + "\" set ('tag.compute' = 'abc')";
    ExceptionChecker.expectThrowsWithMsg(AnalysisException.class, BackendClause.NEED_LOCATION_TAG_MSG, () -> UtFrameUtils.parseAndAnalyzeStmt(alterString, connectContext));
    // Test set multi tag for a Backend when Config.enable_multi_tags is false
    Config.enable_multi_tags = false;
    String alterString2 = "alter system modify backend \"" + be1.getHost() + ":" + be1.getHeartbeatPort() + "\" set ('tag.location' = 'zone3', 'tag.compution' = 'abc')";
    ExceptionChecker.expectThrowsWithMsg(AnalysisException.class, BackendClause.MUTLI_TAG_DISABLED_MSG, () -> UtFrameUtils.parseAndAnalyzeStmt(alterString2, connectContext));
    // Test set multi tag for a Backend when Config.enable_multi_tags is true
    Config.enable_multi_tags = true;
    String stmtStr3 = "alter system modify backend \"" + be1.getHost() + ":" + be1.getHeartbeatPort() + "\" set ('tag.location' = 'zone1', 'tag.compute' = 'c1')";
    AlterSystemStmt stmt = (AlterSystemStmt) UtFrameUtils.parseAndAnalyzeStmt(stmtStr3, connectContext);
    DdlExecutor.execute(Env.getCurrentEnv(), stmt);
    Map<String, String> tagMap = be1.getTagMap();
    Assert.assertEquals(2, tagMap.size());
    Assert.assertEquals("zone1", tagMap.get(Tag.TYPE_LOCATION));
    Assert.assertEquals("c1", tagMap.get("compute"));
    Assert.assertEquals(Tag.createNotCheck(Tag.TYPE_LOCATION, "zone1"), be1.getLocationTag());
    Tag zone1 = Tag.create(Tag.TYPE_LOCATION, "zone1");
    Tag zone2 = Tag.create(Tag.TYPE_LOCATION, "zone2");
    Assert.assertEquals(zone1, backends.get(0).getLocationTag());
    Assert.assertEquals(zone1, backends.get(1).getLocationTag());
    Assert.assertEquals(zone1, backends.get(2).getLocationTag());
    Assert.assertEquals(zone2, backends.get(3).getLocationTag());
    Assert.assertEquals(zone2, backends.get(4).getLocationTag());
    // create table
    // 1. no default tag, create will fail
    String createStr = "create table test.tbl1\n" + "(k1 date, k2 int)\n" + "partition by range(k1)\n" + "(\n" + " partition p1 values less than(\"2021-06-01\"),\n" + " partition p2 values less than(\"2021-07-01\"),\n" + " partition p3 values less than(\"2021-08-01\")\n" + ")\n" + "distributed by hash(k2) buckets 10;";
    ExceptionChecker.expectThrows(DdlException.class, () -> createTable(createStr));
    // nodes of zone2 not enough, create will fail
    // it will fail because of we check tag location during the analysis process, so we check AnalysisException
    String createStr2 = "create table test.tbl1\n" + "(k1 date, k2 int)\n" + "partition by range(k1)\n" + "(\n" + " partition p1 values less than(\"2021-06-01\"),\n" + " partition p2 values less than(\"2021-07-01\"),\n" + " partition p3 values less than(\"2021-08-01\")\n" + ")\n" + "distributed by hash(k2) buckets 10\n" + "properties\n" + "(\n" + "    \"replication_allocation\" = \"tag.location.zone1: 2, tag.location.zone2: 3\"\n" + ")";
    ExceptionChecker.expectThrows(AnalysisException.class, () -> createTable(createStr2));
    // normal, create success
    String createStr3 = "create table test.tbl1\n" + "(k1 date, k2 int)\n" + "partition by range(k1)\n" + "(\n" + " partition p1 values less than(\"2021-06-01\"),\n" + " partition p2 values less than(\"2021-07-01\"),\n" + " partition p3 values less than(\"2021-08-01\")\n" + ")\n" + "distributed by hash(k2) buckets 10\n" + "properties\n" + "(\n" + "    \"replication_allocation\" = \"tag.location.zone1: 2, tag.location.zone2: 1\"\n" + ")";
    ExceptionChecker.expectThrowsNoException(() -> createTable(createStr3));
    Database db = Env.getCurrentInternalCatalog().getDbNullable("test");
    OlapTable tbl = (OlapTable) db.getTableNullable("tbl1");
    // alter table's replica allocation failed, tag not enough
    String alterStr = "alter table test.tbl1" + " set (\"replication_allocation\" = \"tag.location.zone1: 2, tag.location.zone2: 3\");";
    ExceptionChecker.expectThrows(AnalysisException.class, () -> alterTable(alterStr));
    ReplicaAllocation tblReplicaAlloc = tbl.getDefaultReplicaAllocation();
    Assert.assertEquals(3, tblReplicaAlloc.getTotalReplicaNum());
    Assert.assertEquals(Short.valueOf((short) 2), tblReplicaAlloc.getReplicaNumByTag(tag1));
    Assert.assertEquals(Short.valueOf((short) 1), tblReplicaAlloc.getReplicaNumByTag(tag2));
    // alter partition's replica allocation succeed
    String alterStr2 = "alter table test.tbl1 modify partition p1" + " set (\"replication_allocation\" = \"tag.location.zone1: 1, tag.location.zone2: 2\");";
    ExceptionChecker.expectThrowsNoException(() -> alterTable(alterStr2));
    Thread.sleep(5000);
    Partition p1 = tbl.getPartition("p1");
    ReplicaAllocation p1ReplicaAlloc = tbl.getPartitionInfo().getReplicaAllocation(p1.getId());
    Assert.assertEquals(3, p1ReplicaAlloc.getTotalReplicaNum());
    Assert.assertEquals(Short.valueOf((short) 1), p1ReplicaAlloc.getReplicaNumByTag(tag1));
    Assert.assertEquals(Short.valueOf((short) 2), p1ReplicaAlloc.getReplicaNumByTag(tag2));
    // check backend get() methods
    SystemInfoService infoService = Env.getCurrentSystemInfo();
    Set<Tag> tags = infoService.getTags();
    Assert.assertEquals(2, tags.size());
    // check tablet and replica number
    TabletInvertedIndex invertedIndex = Env.getCurrentInvertedIndex();
    Table<Long, Long, Replica> replicaMetaTable = invertedIndex.getReplicaMetaTable();
    Assert.assertEquals(30, replicaMetaTable.rowKeySet().size());
    Assert.assertEquals(5, replicaMetaTable.columnKeySet().size());
    // wait all replica reallocating to correct backend
    checkTableReplicaAllocation(tbl);
    Assert.assertEquals(90, replicaMetaTable.cellSet().size());
    // for now, tbl has 3 partitions:
    // p1: zone1: 1, zone2: 2
    // p2: zone1: 2, zone2: 1
    // p3: zone1: 2, zone2: 1
    // Backends:
    // [0, 1, 2]: zone1
    // [3, 4]:    zone2
    // change backend 2 to zone2
    // set tag for all backends. 0-2 to zone1, 4 and 5 to zone2
    // and wait all replica reallocating to correct backend
    Backend be = backends.get(2);
    String stmtStr = "alter system modify backend \"" + be.getHost() + ":" + be.getHeartbeatPort() + "\" set ('tag.location' = 'zone2')";
    stmt = (AlterSystemStmt) UtFrameUtils.parseAndAnalyzeStmt(stmtStr, connectContext);
    DdlExecutor.execute(Env.getCurrentEnv(), stmt);
    Assert.assertEquals(tag2, be.getLocationTag());
    Thread.sleep(5000);
    checkTableReplicaAllocation(tbl);
    Assert.assertEquals(90, replicaMetaTable.cellSet().size());
    // For now, Backends:
    // [0, 1]:      zone1
    // [2, 3, 4]:   zone2
    // begin to test colocation table
    String createStr4 = "create table test.col_tbl1\n" + "(k1 date, k2 int)\n" + "partition by range(k1)\n" + "(\n" + " partition p1 values less than(\"2021-06-01\"),\n" + " partition p2 values less than(\"2021-07-01\"),\n" + " partition p3 values less than(\"2021-08-01\")\n" + ")\n" + "distributed by hash(k2) buckets 10\n" + "properties\n" + "(\n" + "    \"replication_allocation\" = \"tag.location.zone1: 2, tag.location.zone2: 1\",\n" + "    \"colocate_with\" = \"g1\"\n" + ")";
    ExceptionChecker.expectThrowsNoException(() -> createTable(createStr4));
    String createStr5 = "create table test.col_tbl2\n" + "(k1 date, k2 int)\n" + "partition by range(k1)\n" + "(\n" + " partition p1 values less than(\"2021-06-01\"),\n" + " partition p2 values less than(\"2021-07-01\"),\n" + " partition p3 values less than(\"2021-08-01\")\n" + ")\n" + "distributed by hash(k2) buckets 10\n" + "properties\n" + "(\n" + "    \"replication_allocation\" = \"tag.location.zone1: 2, tag.location.zone2: 1\",\n" + "    \"colocate_with\" = \"g1\"\n" + ")";
