public void testFetchResult() throws AnalysisException {
    List<Index> indexes = new ArrayList<>();
    Index indexBitmap = new Index(1, "bitmap_index", Lists.newArrayList("col_1"), IndexType.BITMAP, null, "bitmap index on col_1");
    Map<String, String> invertedProperties = new HashMap<>();
    invertedProperties.put("parser", "unicode");
    Index indexInverted = new Index(2, "inverted_index", Lists.newArrayList("col_2"), IndexType.INVERTED, invertedProperties, "inverted index on col_2");
    Index indexBf = new Index(3, "bloomfilter_index", Lists.newArrayList("col_3"), IndexType.BLOOMFILTER, null, "bloomfilter index on col_3");
