    //         0L))
    add(Range.equal(trinoConnectorColumnMetadataMap.get("c_long_timestamp").getType(), new LongTimestamp(1000001L, 0))).add(Range.equal(trinoConnectorColumnMetadataMap.get("c_long_timestamp_timezone").getType(), LongTimestampWithTimeZone.fromEpochMillisAndFraction(1000L, 1000000, TimeZoneKey.getTimeZoneKey("Asia/Shanghai")))).build();
    for (int i = 0; i < slotRefs.size(); i++) {
        final String colName = slotRefs.get(i).getColumnName();
        Domain inDomain = Domain.create(ValueSet.ofRanges(Lists.newArrayList(expectRanges.get(i))), false);
        Domain notInDomain = Domain.create(ValueSet.all(trinoConnectorColumnMetadataMap.get(colName).getType()).subtract(ValueSet.ofRanges(expectRanges.get(i))), false);
        TupleDomain<ColumnHandle> inTupleDomain = TupleDomain.withColumnDomains(ImmutableMap.of(trinoConnectorColumnHandleMap.get(colName), inDomain));
        TupleDomain<ColumnHandle> notInTupleDomain = TupleDomain.withColumnDomains(ImmutableMap.of(trinoConnectorColumnHandleMap.get(colName), notInDomain));
        expectInTupleDomain.add(inTupleDomain);
        expectNotInTupleDomain.add(notInTupleDomain);
    }
    // test results, construct equal binary predicate
    List<TupleDomain<ColumnHandle>> testTupleDomain = Lists.newArrayList();
    for (int i = 0; i < slotRefs.size(); i++) {
        InPredicate expr = new InPredicate(slotRefs.get(i), literalList.get(i), false);
        TupleDomain<ColumnHandle> tupleDomain = trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(expr);
        testTupleDomain.add(tupleDomain);
    }
    // verify if `testTupleDomain` is equal to `expectTupleDomain`.
    for (int i = 0; i < expectInTupleDomain.size(); i++) {
        Assert.assertTrue(expectInTupleDomain.get(i).contains(testTupleDomain.get(i)));
    }
    testTupleDomain.clear();
    for (int i = 0; i < slotRefs.size(); i++) {
        InPredicate expr = new InPredicate(slotRefs.get(i), literalList.get(i), true);
        TupleDomain<ColumnHandle> tupleDomain = trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(expr);
        testTupleDomain.add(tupleDomain);
    }
    // verify if `testTupleDomain` is equal to `expectTupleDomain`.
    for (int i = 0; i < expectNotInTupleDomain.size(); i++) {
        Assert.assertTrue(expectNotInTupleDomain.get(i).contains(testTupleDomain.get(i)));
    }
}

@Test
public void testCompoundPredicate() throws AnalysisException {
    // construct slotRefs and literalLists
    List<SlotRef> slotRefs = mockSlotRefs();
    List<LiteralExpr> literalList = mockLiteralExpr();
    // valid expr
    List<Expr> validExprs = Lists.newArrayList();
    for (int i = 0; i < slotRefs.size(); i++) {
        BinaryPredicate expr = new BinaryPredicate(BinaryPredicate.Operator.EQ, slotRefs.get(i), literalList.get(i));
        validExprs.add(expr);
    }
    // invalid expr
    BinaryPredicate invalidExpr = new BinaryPredicate(BinaryPredicate.Operator.EQ, literalList.get(0), literalList.get(0));
    // AND
    // valid AND valid
    for (int i = 0; i < validExprs.size(); i++) {
        for (int j = 0; j < validExprs.size(); j++) {
            CompoundPredicate andPredicate = new CompoundPredicate(CompoundPredicate.Operator.AND, validExprs.get(i), validExprs.get(j));
            trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(andPredicate);
        }
    }
    // valid AND invalid
    CompoundPredicate andPredicate = new CompoundPredicate(CompoundPredicate.Operator.AND, validExprs.get(0), invalidExpr);
    trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(andPredicate);
    // invalid AND valid
    andPredicate = new CompoundPredicate(CompoundPredicate.Operator.AND, invalidExpr, validExprs.get(0));
    trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(andPredicate);
    // invalid AND invalid
    andPredicate = new CompoundPredicate(CompoundPredicate.Operator.AND, invalidExpr, invalidExpr);
    try {
        trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(andPredicate);
    } catch (AnalysisException e) {
        Assert.assertTrue(e.getMessage().contains("Can not convert both sides of compound predicate"));
    }
    // OR
    // valid OR valid
    for (int i = 0; i < validExprs.size(); i++) {
        for (int j = 0; j < validExprs.size(); j++) {
            CompoundPredicate orPredicate = new CompoundPredicate(CompoundPredicate.Operator.OR, validExprs.get(i), validExprs.get(j));
            trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(orPredicate);
        }
    }
    // // valid OR valid
    try {
        CompoundPredicate orPredicate = new CompoundPredicate(CompoundPredicate.Operator.AND, validExprs.get(0), invalidExpr);
        trinoConnectorPredicateConverter.convertExprToTrinoTupleDomain(orPredicate);
    } catch (AnalysisException e) {
        Assert.assertTrue(e.getMessage().contains("slotRef is null in binaryPredicateConverter"));
    }
}

