public void test1() throws DdlException {
    /*
         * data description:
         *  table 1 -> partition[10] file1
         *  table 1 -> partition[10] file2
         *  table 2 -> partition[]   file3
         *  table 3 -> partition[11, 12]   file4
         *
         * output:
