public void testTableSync() {
    // normal
    boolean sync = refreshSnapshot.equalsWithBaseTable(mvExistPartitionName, baseExistTableId, new MTMVVersionSnapshot(correctVersion));
    Assert.assertTrue(sync);
    // non exist mv partition
    sync = refreshSnapshot.equalsWithBaseTable("mvp2", baseExistTableId, new MTMVVersionSnapshot(correctVersion));
