@Test
public void testShowViewPriv() throws UserException {
    UserIdentity userIdentity = new UserIdentity("viewUser", "%");
    createUser(userIdentity);
    // `load_priv` and `select_priv` can not `show create view`
    GrantStmt grantStmt = new GrantStmt(userIdentity, null, new TablePattern("viewdb", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.SELECT_PRIV), new AccessPrivilegeWithCols(AccessPrivilege.LOAD_PRIV)));
    grant(grantStmt);
    Assert.assertFalse(accessManager.checkDbPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "viewdb", PrivPredicate.SHOW_VIEW));
    // `SHOW_VIEW_PRIV` can `show create view`
    grantStmt = new GrantStmt(userIdentity, null, new TablePattern("viewdb", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.SHOW_VIEW_PRIV)));
    grant(grantStmt);
    Assert.assertTrue(accessManager.checkDbPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "viewdb", PrivPredicate.SHOW_VIEW));
    RevokeStmt revokeStmt = new RevokeStmt(userIdentity, null, new TablePattern("viewdb", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.SHOW_VIEW_PRIV)));
    revoke(revokeStmt);
    // 'admin_priv' can `show create view`
    grantStmt = new GrantStmt(userIdentity, null, new TablePattern("*", "*", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.ADMIN_PRIV)));
    grant(grantStmt);
    Assert.assertTrue(accessManager.checkDbPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "viewdb", PrivPredicate.SHOW_VIEW));
    revokeStmt = new RevokeStmt(userIdentity, null, new TablePattern("*", "*", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.ADMIN_PRIV)));
    revoke(revokeStmt);
    // 'create_priv' can `show create view`
    grantStmt = new GrantStmt(userIdentity, null, new TablePattern("viewdb", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.CREATE_PRIV)));
    grant(grantStmt);
    Assert.assertTrue(accessManager.checkDbPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "viewdb", PrivPredicate.SHOW_VIEW));
    revokeStmt = new RevokeStmt(userIdentity, null, new TablePattern("viewdb", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.CREATE_PRIV)));
    revoke(revokeStmt);
    // 'alter_priv' can `show create view`
    grantStmt = new GrantStmt(userIdentity, null, new TablePattern("viewdb", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.ALTER_PRIV)));
    grant(grantStmt);
    Assert.assertTrue(accessManager.checkDbPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "viewdb", PrivPredicate.SHOW_VIEW));
    revokeStmt = new RevokeStmt(userIdentity, null, new TablePattern("viewdb", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.ALTER_PRIV)));
    revoke(revokeStmt);
    // 'drop_priv' can `show create view`
    grantStmt = new GrantStmt(userIdentity, null, new TablePattern("viewdb", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.DROP_PRIV)));
    grant(grantStmt);
    Assert.assertTrue(accessManager.checkDbPriv(userIdentity, InternalCatalog.INTERNAL_CATALOG_NAME, "viewdb", PrivPredicate.SHOW_VIEW));
    revokeStmt = new RevokeStmt(userIdentity, null, new TablePattern("viewdb", "*"), Lists.newArrayList(new AccessPrivilegeWithCols(AccessPrivilege.DROP_PRIV)));
    revoke(revokeStmt);
}

