@Test
void testStarQuery() {
    //      t1
    //      |
    //t3-- t0 -- t4
    //      |
    //     t2
    HyperGraph hyperGraph = new HyperGraphBuilder().init(10, 20, 30, 40, 50).addEdge(JoinType.INNER_JOIN, 0, 1).addEdge(JoinType.INNER_JOIN, 0, 2).addEdge(JoinType.INNER_JOIN, 0, 3).addEdge(JoinType.INNER_JOIN, 0, 4).build();
    GraphSimplifier graphSimplifier = new GraphSimplifier(hyperGraph);
    List<Pair<Long, Long>> steps = ImmutableList.<Pair<Long, Long>>builder().add(// 04   - 1
    Pair.of(17L, 2L)).add(// 04   - 2
    Pair.of(17L, 4L)).add(// 04   - 3
    Pair.of(17L, 8L)).add(// 041  - 2
    Pair.of(19L, 8L)).add(// 042  - 1
    Pair.of(21L, 2L)).add(// 0134 - 2
    Pair.of(23L, 8L)).// 0-4-3-1-2 : big left deep tree
    build();
    for (Pair<Long, Long> step : steps) {
        if (!graphSimplifier.applySimplificationStep()) {
            break;
        }
        System.out.println(graphSimplifier.getLastAppliedSteps());
        Assertions.assertEquals(step, graphSimplifier.getLastAppliedSteps());
    }
    Counter counter = new Counter();
    SubgraphEnumerator subgraphEnumerator = new SubgraphEnumerator(counter, hyperGraph);
    subgraphEnumerator.enumerate();
    for (int count : counter.getAllCount().values()) {
        Assertions.assertTrue(count < 10);
    }
    Assertions.assertTrue(graphSimplifier.isTotalOrder());
}

