@Test
public void testSatisfyNaturalHash() {
    Map<ExprId, Integer> natural1Map = Maps.newHashMap();
    natural1Map.put(new ExprId(0), 0);
    natural1Map.put(new ExprId(1), 0);
    natural1Map.put(new ExprId(2), 1);
    natural1Map.put(new ExprId(3), 1);
    DistributionSpecHash natural1 = new DistributionSpecHash(Lists.newArrayList(new ExprId(0), new ExprId(2)), ShuffleType.NATURAL, 0, Sets.newHashSet(0L), Lists.newArrayList(Sets.newHashSet(new ExprId(0), new ExprId(1)), Sets.newHashSet(new ExprId(2), new ExprId(3))), natural1Map);
    Map<ExprId, Integer> natural2Map = Maps.newHashMap();
    natural2Map.put(new ExprId(1), 0);
    natural2Map.put(new ExprId(2), 1);
    DistributionSpecHash natural2 = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(2)), ShuffleType.NATURAL, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1)), Sets.newHashSet(new ExprId(2))), natural2Map);
    Map<ExprId, Integer> natural3Map = Maps.newHashMap();
    natural3Map.put(new ExprId(2), 0);
    natural3Map.put(new ExprId(1), 1);
    DistributionSpecHash natural3 = new DistributionSpecHash(Lists.newArrayList(new ExprId(2), new ExprId(1)), ShuffleType.NATURAL, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(2)), Sets.newHashSet(new ExprId(1))), natural3Map);
    DistributionSpecHash require = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(2)), ShuffleType.REQUIRE, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1)), Sets.newHashSet(new ExprId(2))), natural2Map);
    DistributionSpecHash storageBucketed = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(2)), ShuffleType.STORAGE_BUCKETED, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1)), Sets.newHashSet(new ExprId(2))), natural2Map);
    DistributionSpecHash executionBucketed = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(2)), ShuffleType.EXECUTION_BUCKETED, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1)), Sets.newHashSet(new ExprId(2))), natural2Map);
    // require is same order
    Assertions.assertTrue(natural1.satisfy(natural2));
    // require contains all sets but order is not same
    Assertions.assertFalse(natural1.satisfy(natural3));
    // require slots is not contained by target
    Assertions.assertFalse(natural2.satisfy(natural1));
    // other shuffle type with same order
    Assertions.assertFalse(require.satisfy(natural2));
    Assertions.assertFalse(executionBucketed.satisfy(natural2));
    Assertions.assertFalse(storageBucketed.satisfy(natural2));
}

