    DistributionSpecHash require2 = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(2)), ShuffleType.REQUIRE, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1)), Sets.newHashSet(new ExprId(2))), require2Map);
    Map<ExprId, Integer> require3Map = Maps.newHashMap();
    require3Map.put(new ExprId(2), 0);
    require3Map.put(new ExprId(1), 1);
    DistributionSpecHash require3 = new DistributionSpecHash(Lists.newArrayList(new ExprId(2), new ExprId(1)), ShuffleType.REQUIRE, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(2)), Sets.newHashSet(new ExprId(1))), require3Map);
    DistributionSpecHash natural = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(2)), ShuffleType.NATURAL, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1)), Sets.newHashSet(new ExprId(2))), require2Map);
    DistributionSpecHash storageBucketed = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(2)), ShuffleType.STORAGE_BUCKETED, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1)), Sets.newHashSet(new ExprId(2))), require2Map);
    DistributionSpecHash executionBucketed = new DistributionSpecHash(Lists.newArrayList(new ExprId(1), new ExprId(2)), ShuffleType.EXECUTION_BUCKETED, 1, Sets.newHashSet(1L), Lists.newArrayList(Sets.newHashSet(new ExprId(1)), Sets.newHashSet(new ExprId(2))), require2Map);
    // require is same order
    Assertions.assertTrue(require1.satisfy(require2));
    // require contains all sets but order is not same
    Assertions.assertTrue(require1.satisfy(require3));
    // require slots is not contained by target
    Assertions.assertFalse(require3.satisfy(require1));
    // other shuffle type with same order
    Assertions.assertTrue(natural.satisfy(require2));
    Assertions.assertTrue(executionBucketed.satisfy(require2));
    Assertions.assertTrue(storageBucketed.satisfy(require2));
    // other shuffle type contain all set but order is not same
    Assertions.assertTrue(natural.satisfy(require3));
    Assertions.assertTrue(executionBucketed.satisfy(require3));
    Assertions.assertTrue(storageBucketed.satisfy(require3));
}

