@Test
public void testDefaultFunctionNameIsClassName() {
    // we register Year by the code in FunctionRegistry: scalar(Year.class).
    // and default class name should be year.
    PlanChecker.from(connectContext).analyze("select year('2021-01-01')").matches(logicalProject().when(project -> {
        Year year = (Year) project.getProjects().get(0).child(0);
