void testProjectLiteral() {
    List<NamedExpression> projectExprs = ImmutableList.of(new Alias(new Add(scan1.getOutput().get(0), Literal.of(1)), "alias"), new Alias(scan2.getOutput().get(0).getExprId(), new NullLiteral(), scan2.getOutput().get(0).getName()));
    // complex projection contain ti.id, which isn't in Join Condition
    LogicalPlan plan = new LogicalPlanBuilder(scan1).join(scan2, JoinType.LEFT_SEMI_JOIN, Pair.of(1, 1)).projectExprs(projectExprs).join(scan3, JoinType.INNER_JOIN, Pair.of(1, 1)).build();
