@Test
public void testSemiProjectSemiCommute() {
    /*
         *     t1.name=t3.name              t1.id=t2.id
         *       topJoin                  newTopJoin
         *       /     \                   /        \
         *    project   t3        t1.name=t3.name    t2
         *    t1.name       -->    newBottomJoin
         *      |                     /    \
         * t1.id=t2.id             t1      t3
         * bottomJoin
         *   /    \
         * t1      t2
         */
    LogicalPlan topJoin = new LogicalPlanBuilder(scan1).join(scan2, JoinType.LEFT_ANTI_JOIN, Pair.of(0, 0)).project(ImmutableList.of(1)).join(scan3, JoinType.LEFT_SEMI_JOIN, Pair.of(0, 1)).projectAll().build();
    PlanChecker.from(MemoTestUtils.createConnectContext(), topJoin).applyExploration(SemiJoinSemiJoinTransposeProject.INSTANCE.build()).printlnExploration().matchesExploration(logicalProject(logicalJoin(logicalProject(logicalJoin(logicalOlapScan().when(scan -> scan.getTable().getName().equals("t1")), logicalOlapScan().when(scan -> scan.getTable().getName().equals("t3"))).when(join -> join.getJoinType() == JoinType.LEFT_SEMI_JOIN)), logicalProject(logicalOlapScan().when(scan -> scan.getTable().getName().equals("t2")))).when(join -> join.getJoinType() == JoinType.LEFT_ANTI_JOIN)));
}

@Test
public void testSemiProjectSemiCommuteMarkJoin() {
    LogicalPlan topJoin = new LogicalPlanBuilder(scan1).markJoin(scan2, JoinType.LEFT_SEMI_JOIN, Pair.of(0, 0)).project(ImmutableList.of(0, 2)).markJoin(scan3, JoinType.LEFT_SEMI_JOIN, Pair.of(0, 1)).projectAll().build();
    PlanChecker.from(MemoTestUtils.createConnectContext(), topJoin).applyExploration(SemiJoinSemiJoinTransposeProject.INSTANCE.build()).matchesExploration(logicalProject(logicalJoin(logicalProject(logicalJoin(logicalOlapScan().when(scan -> scan.getTable().getName().equals("t1")), logicalOlapScan().when(scan -> scan.getTable().getName().equals("t3"))).when(join -> join.getJoinType() == JoinType.LEFT_SEMI_JOIN)).when(project -> project.getProjects().size() == 2), logicalProject(logicalOlapScan().when(scan -> scan.getTable().getName().equals("t2")))).when(join -> join.getJoinType() == JoinType.LEFT_SEMI_JOIN)));
}

