@Test
void testFoldString() {
    executor = new ExpressionRuleExecutor(ImmutableList.of(bottomUp(FoldConstantRuleOnFE.VISITOR_INSTANCE)));
    ConvertTz c = new ConvertTz(DateTimeV2Literal.fromJavaDateType(LocalDateTime.of(1, 1, 1, 1, 1, 1)), StringLiteral.of("Asia/Shanghai"), StringLiteral.of("GMT"));
    Expression rewritten = executor.rewrite(c, context);
    Assertions.assertTrue(new DateTimeV2Literal("0000-12-31 16:55:18.000000").compareTo((Literal) rewritten) == 0);
    c = new ConvertTz(DateTimeV2Literal.fromJavaDateType(LocalDateTime.of(9999, 12, 31, 23, 59, 59, 999999000)), StringLiteral.of("Pacific/Galapagos"), StringLiteral.of("Pacific/Galapagos"));
    rewritten = executor.rewrite(c, context);
