    assertDeterminateEvaluable("P1 = '20240614' and not(P2 = '20240614') or 'a' = 'b'", true);
    assertDeterminateEvaluable("P1 = '20240614' and P2 = '20240614' or not('a' = 'b')", true);
    assertDeterminateEvaluable("P1 = '20240614' and " + "case when(P2 = '20240614' or P2 = 'abc') then P3 = 'abc' else false end", true);
    assertDeterminateEvaluable("P1 = '20240614' and " + "case when(P2 = '20240614' and P1 = 'abc') then P3 = 'abc' else false end", true);
    assertDeterminateEvaluable("P1 = '20240614' and " + "if(P2 = '20240614' and P1 = 'abc', P3 = 'abc', false)", true);
    assertDeterminateEvaluable("P1 = '20240614' and " + "if(P2 = '20240614' and '123' = 'abc', P1 = 'abc', false)", true);
    assertDeterminateEvaluable("P1 = '20240614' and " + "to_date('20240614', '%Y%m%d') = P2", true);
    // expression contains non-partition slot.
    assertDeterminateEvaluable("P1 = '20240614' and P2 = '20240614' and I1 = 'abc'", false);
    assertDeterminateEvaluable("P1 = '20240614' and P2 = '20240614' or I1 = 'abc'", false);
    assertDeterminateEvaluable("P1 = '20240614' and (P2 = '20240614' and I1 = 'abc')", false);
    assertDeterminateEvaluable("P1 = '20240614' and (P2 = '20240614' or I1 = 'abc')", false);
    assertDeterminateEvaluable("P1 = '20240614' and (P2 = '20240614' or I1 = 'abc')", false);
    assertDeterminateEvaluable("P1 = '20240614' and not(P2 = '20240614') or 'S1' = 'b'", true);
    assertDeterminateEvaluable("P1 = '20240614' and P2 = '20240614' or not('S2' = 'b')", true);
    assertDeterminateEvaluable("P1 = '20240614' and " + "case when(P2 = '20240614' or I1 = 'abc') then I2 = 'abc' else false end", false);
    assertDeterminateEvaluable("P1 = '20240614' and " + "case when(P2 = '20240614' and I1 = 'abc') then I2 = 'abc' else false end", false);
    assertDeterminateEvaluable("P1 = '20240614' and " + "if(P2 = '20240614' and I1 = 'abc', I2 = 'abc', false)", false);
    assertDeterminateEvaluable("P1 = '20240614' and " + "if(P2 = '20240614' and I1 = 'abc', I2 = 'abc', false)", false);
    assertDeterminateEvaluable("P1 = '20240614' and " + "to_date('20240614', '%Y%m%d') = S1", false);
    assertDeterminateEvaluable("P1 = '20240614' and " + "(select 'a' from t limit 1) = S1", false);
}

