@Test
void dateLikeOverflow() {
    PlanChecker.from(connectContext).analyze("select CAST('2021-01-32 00:00:00' AS DATETIME(6))").rewrite().matches(logicalResultSink(logicalOneRowRelation().when(p -> p.getProjects().get(0).child(0).equals(new NullLiteral(DateTimeV2Type.of(6))))));
    PlanChecker.from(connectContext).analyze("select CONVERT('2021-01-32 00:00:00', DATETIME(6))").rewrite().matches(logicalResultSink(logicalOneRowRelation().when(p -> p.getProjects().get(0).child(0).equals(new NullLiteral(DateTimeV2Type.of(6))))));
    PlanChecker.from(connectContext).analyze("select CONVERT_TZ('2021-01-32 00:00:00', '+08:00', 'America/London') = '2021-01-30'").rewrite().matches(logicalResultSink(logicalOneRowRelation().when(p -> p.getProjects().get(0).child(0) instanceof NullLiteral)));
    PlanChecker.from(connectContext).analyze("select CONVERT_TZ('2021-01-32 00:00:00', '+08:00', 'America/London')").rewrite().matches(logicalResultSink(logicalOneRowRelation().when(p -> p.getProjects().get(0).child(0) instanceof NullLiteral)));
    PlanChecker.from(connectContext).analyze("select CONVERT_TZ('2021-01-32 00:00:00.0000001', '+08:00', 'America/London')").rewrite().matches(logicalResultSink(logicalOneRowRelation().when(p -> p.getProjects().get(0).child(0) instanceof NullLiteral)));
    PlanChecker.from(connectContext).analyze("select CONVERT_TZ('2021-01-32 00:00:00.001', '+08:00', 'America/London') = '2021-01-30'").rewrite().matches(logicalResultSink(logicalOneRowRelation().when(p -> p.getProjects().get(0).child(0) instanceof NullLiteral)));
    Assertions.assertThrows(AnalysisException.class, () -> PlanChecker.from(connectContext).analyze("select CAST('2021-01-32 00:00:00' AS DATETIME(6)) = '2021-01-32 00:00:00'").rewrite());
    Assertions.assertThrows(AnalysisException.class, () -> PlanChecker.from(connectContext).analyze("select CAST('2021-01-32 00:00:00' AS DATETIME(6)) = '2021-01-32 23:00:00'").rewrite());
    Assertions.assertThrows(AnalysisException.class, () -> PlanChecker.from(connectContext).analyze("select CAST('2021-01-32 00:00:00' AS DATETIME(6)) = '1000'").rewrite());
}

