    assertRewrite(new GreaterThan(new Cast(dt, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new GreaterThan(dt, dt));
    // DateTimeV2 -> DateV2
    assertRewrite(new GreaterThan(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new GreaterThan(dv2, dv2));
    assertRewrite(new LessThan(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new LessThan(dv2, dv2PlusOne));
    assertRewrite(new EqualTo(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new EqualTo(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2));
    assertRewrite(new EqualTo(new Cast(d, DateTimeV2Type.SYSTEM_DEFAULT), dtv2), new EqualTo(new Cast(d, DateTimeV2Type.SYSTEM_DEFAULT), dtv2));
    // test hour, minute and second all zero
    Expression dtv2AtZeroClock = new DateTimeV2Literal(1, 1, 1, 0, 0, 0, 0);
    assertRewrite(new GreaterThan(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2AtZeroClock), new GreaterThan(dv2, dv2));
    assertRewrite(new LessThan(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2AtZeroClock), new LessThan(dv2, dv2));
    assertRewrite(new EqualTo(new Cast(dv2, DateTimeV2Type.SYSTEM_DEFAULT), dtv2AtZeroClock), new EqualTo(dv2, dv2));
}

