/**
 * select rank() over(partition by id, gender), sum(age) over(partition by gender, id, gender) from student
 *
 * rank and sum have same WindowFrame and compatible partitionKeys, so they can be put to one PhysicalWindow
 */
@Test
public void testPartitionKeyCompatible() {
    NamedExpression id = rStudent.getOutput().get(0).toSlot();
    NamedExpression gender = rStudent.getOutput().get(1).toSlot();
    NamedExpression age = rStudent.getOutput().get(3).toSlot();
    List<Expression> pkList1 = ImmutableList.of(id, gender);
    List<Expression> pkList2 = ImmutableList.of(gender, id, gender);
    WindowFrame windowFrame = new WindowFrame(WindowFrame.FrameUnitsType.RANGE, WindowFrame.FrameBoundary.newPrecedingBoundary(), WindowFrame.FrameBoundary.newCurrentRowBoundary());
    WindowExpression window1 = new WindowExpression(new Rank(), pkList1, ImmutableList.of(), windowFrame);
    WindowExpression window2 = new WindowExpression(new Sum(age), pkList2, ImmutableList.of(), windowFrame);
    Alias windowAlias1 = new Alias(window1, window1.toSql());
    Alias windowAlias2 = new Alias(window2, window2.toSql());
    List<NamedExpression> expressions = Lists.newArrayList(windowAlias1, windowAlias2);
    Plan root = new LogicalWindow<>(expressions, rStudent).withChecked(expressions, rStudent);
    PlanChecker.from(MemoTestUtils.createConnectContext(), root).applyImplementation(new LogicalWindowToPhysicalWindow().build()).matches(physicalWindow().when(physicalWindow -> {
        WindowFrameGroup wfg = physicalWindow.getWindowFrameGroup();
        List<NamedExpression> windows = wfg.getGroups();
        return windows.get(0).equals(windowAlias1) && windows.get(1).equals(windowAlias2) && CollectionUtils.isEqualCollection(wfg.getPartitionKeys(), pkList1) && wfg.getWindowFrame().equals(windowFrame);
    }));
}

/**
 * <pre>
 * the initial plan is:
 *   Aggregate(phase: [GLOBAL], outputExpr: [age, SUM(id) as sum], groupByExpr: [age])
 *   +--childPlan(id, name, age)
 * we should rewrite to:
 *   Aggregate(phase: [GLOBAL], outputExpr: [a, SUM(b) as c], groupByExpr: [a])
 *   +--Aggregate(phase: [LOCAL], outputExpr: [age as a, SUM(id) as b], groupByExpr: [age])
 *       +--childPlan(id, name, age)
 * </pre>
 */
@Test
public void slotReferenceGroupBy() {
    List<Expression> groupExpressionList = Lists.newArrayList(rStudent.getOutput().get(2).toSlot());
    List<NamedExpression> outputExpressionList = Lists.newArrayList(rStudent.getOutput().get(2).toSlot(), new Alias(new Sum(rStudent.getOutput().get(0).toSlot()), "sum"));
    Plan root = new LogicalAggregate<>(groupExpressionList, outputExpressionList, true, Optional.empty(), rStudent);
    Expression localOutput0 = rStudent.getOutput().get(2).toSlot();
    Sum localOutput1 = new Sum(rStudent.getOutput().get(0).toSlot());
    Slot localGroupBy = rStudent.getOutput().get(2).toSlot();
    PlanChecker.from(MemoTestUtils.createConnectContext(), root).applyImplementation(twoPhaseAggregateWithoutDistinct()).matches(physicalHashAggregate(physicalHashAggregate().when(agg -> agg.getAggPhase().equals(AggPhase.LOCAL)).when(agg -> agg.getOutputExpressions().size() == 2).when(agg -> agg.getOutputExpressions().get(0).equals(localOutput0)).when(agg -> agg.getOutputExpressions().get(1).child(0).child(0).children().equals(localOutput1.children())).when(agg -> agg.getGroupByExpressions().size() == 1).when(agg -> agg.getGroupByExpressions().get(0).equals(localGroupBy))).when(agg -> agg.getAggPhase().equals(AggPhase.GLOBAL)).when(agg -> agg.getOutputExpressions().size() == 2).when(agg -> agg.getOutputExpressions().get(0).equals(agg.child().getOutputExpressions().get(0).toSlot())).when(agg -> agg.getOutputExpressions().get(1).child(0).child(0).equals(agg.child().getOutputExpressions().get(1).toSlot())).when(agg -> agg.getGroupByExpressions().size() == 1).when(agg -> agg.getGroupByExpressions().get(0).equals(agg.child().getOutputExpressions().get(0).toSlot())).// check id:
    when(agg -> agg.getOutputExpressions().get(0).getExprId().equals(outputExpressionList.get(0).getExprId())).when(agg -> agg.getOutputExpressions().get(1).getExprId().equals(outputExpressionList.get(1).getExprId())));
}

/**
 * <pre>
 * the initial plan is:
 *   Aggregate(phase: [GLOBAL], outputExpr: [SUM(id) as sum], groupByExpr: [])
 *   +--childPlan(id, name, age)
 * we should rewrite to:
 *   Aggregate(phase: [GLOBAL], outputExpr: [SUM(b) as b], groupByExpr: [])
 *   +--Aggregate(phase: [LOCAL], outputExpr: [SUM(id) as a], groupByExpr: [])
 *       +--childPlan(id, name, age)
 * </pre>
 */
@Test
