/**
 * project2(X + 2) -> project1(B, C, A+1 as X)
 * transform to :
 * project2((A + 1) + 2)
 */
@Test
public void testMergeConsecutiveProjectsWithAlias() {
    Alias alias = new Alias(new Add(score.getOutput().get(0), Literal.of(1)), "X");
    LogicalProject<LogicalOlapScan> bottomProject = new LogicalProject<>(Lists.newArrayList(score.getOutput().get(1), score.getOutput().get(2), alias), score);
    LogicalProject<LogicalProject<LogicalOlapScan>> topProject = new LogicalProject<>(Lists.newArrayList(new Alias(new Add(bottomProject.getOutput().get(2), Literal.of(2)), "Y")), bottomProject);
    PlanChecker.from(MemoTestUtils.createConnectContext(), topProject).applyTopDown(new MergeProjects()).matches(logicalProject(logicalOlapScan()).when(project -> Objects.equals(project.getProjects().toString(), "[((sid#0 + 1) + 2) AS `Y`#4]")));
}

