@Test
void testFilterMV4() throws Exception {
    String createMVSql = "create materialized view " + EMPS_MV_NAME + " as select name, deptno, salary from " + EMPS_TABLE_NAME + " where deptno > 0;";
    String query1 = "select name from " + EMPS_TABLE_NAME + " where " + EMPS_TABLE_NAME + ".deptno > 0;";
    createMv(createMVSql);
    ConnectContext.get().getState().setNereids(true);
    Env.getCurrentEnv().getCurrentCatalog().getDbOrAnalysisException("db1").getOlapTableOrDdlException(EMPS_TABLE_NAME).getIndexIdToMeta().forEach((id, meta) -> {
        if (meta.getWhereClause() != null) {
            meta.getWhereClause().setDisableTableName(false);
        }
