@Test
public void testPreAggHint() throws Exception {
    createTable(" CREATE TABLE `test_preagg_hint` (\n" + "  `k1` int(11) NULL,\n" + "  `k2` int(11) NULL,\n" + "  `v1` int(11) SUM NULL,\n" + "  `v2` int(11) SUM NULL\n" + ") ENGINE=OLAP\n" + "AGGREGATE KEY(`k1`, `k2`)\n" + "COMMENT 'OLAP'\n" + "DISTRIBUTED BY HASH(`k1`) BUCKETS 3\n" + "PROPERTIES (\n" + "\"replication_allocation\" = \"tag.location.default: 1\",\n" + "\"in_memory\" = \"false\",\n" + "\"storage_format\" = \"V2\",\n" + "\"disable_auto_compaction\" = \"false\"\n" + ");");
    addRollup("alter table test_preagg_hint add rollup r1(k1, k2, v1)");
    // no pre-agg hint
    String queryWithoutHint = "select k1, v1 from test_preagg_hint";
    // legacy planner
    Assertions.assertTrue(getSQLPlanOrErrorMsg(queryWithoutHint).contains("TABLE: test.test_preagg_hint(r1), PREAGGREGATION: OFF. Reason: No AggregateInfo"));
    // nereids planner
    PlanChecker.from(connectContext).analyze(queryWithoutHint).rewrite().matches(logicalOlapScan().when(scan -> {
        Assertions.assertTrue(scan.getHints().isEmpty());
        Assertions.assertEquals("r1", scan.getSelectedMaterializedIndexName().get());
        PreAggStatus preAggStatus = scan.getPreAggStatus();
        Assertions.assertTrue(preAggStatus.isOff());
        Assertions.assertEquals("No aggregate on scan.", preAggStatus.getOffReason());
        return true;
    }));
    // has pre-agg hint
    String queryWithHint = "select k1, v1 from test_preagg_hint /*+ PREAGGOPEN*/";
    // legacy planner
    Assertions.assertTrue(getSQLPlanOrErrorMsg(queryWithHint).contains("TABLE: test.test_preagg_hint(r1), PREAGGREGATION: ON"));
    // nereids planner
    PlanChecker.from(connectContext).analyze(queryWithHint).rewrite().matches(logicalOlapScan().when(scan -> {
        Assertions.assertEquals(1, scan.getHints().size());
        Assertions.assertEquals("PREAGGOPEN", scan.getHints().get(0));
        Assertions.assertEquals("r1", scan.getSelectedMaterializedIndexName().get());
        PreAggStatus preAggStatus = scan.getPreAggStatus();
        Assertions.assertTrue(preAggStatus.isOn());
        return true;
    }));
    dropTable("test_preagg_hint", true);
}

