@Test
public void testWithoutProject() {
    LogicalOlapScan olapScan = PlanConstructor.newLogicalOlapScan(1, "tbl", 0);
    LogicalAggregate<LogicalOlapScan> aggregate;
    CascadesContext context;
    // min max
    aggregate = new LogicalAggregate<>(Collections.emptyList(), ImmutableList.of(new Alias(new Min(olapScan.getOutput().get(0)), "min")), true, Optional.empty(), olapScan);
    context = MemoTestUtils.createCascadesContext(aggregate);
    PlanChecker.from(context).applyImplementation(storageLayerAggregateWithoutProject()).matches(logicalAggregate(physicalStorageLayerAggregate().when(agg -> agg.getAggOp() == PushDownAggOp.MIN_MAX)));
    // count
    aggregate = new LogicalAggregate<>(Collections.emptyList(), ImmutableList.of(new Alias(new Count(olapScan.getOutput().get(0)), "count")), true, Optional.empty(), olapScan);
    context = MemoTestUtils.createCascadesContext(aggregate);
    PlanChecker.from(context).applyImplementation(storageLayerAggregateWithoutProject()).matches(logicalAggregate(physicalStorageLayerAggregate().when(agg -> agg.getAggOp() == PushDownAggOp.COUNT)));
    // mix
    aggregate = new LogicalAggregate<>(Collections.emptyList(), ImmutableList.of(new Alias(new Count(olapScan.getOutput().get(0)), "count"), new Alias(new Max(olapScan.getOutput().get(0)), "max")), true, Optional.empty(), olapScan);
    context = MemoTestUtils.createCascadesContext(aggregate);
    PlanChecker.from(context).applyImplementation(storageLayerAggregateWithoutProject()).matches(logicalAggregate(physicalStorageLayerAggregate().when(agg -> agg.getAggOp() == PushDownAggOp.MIX)));
}

