public void testWithProject() {
    LogicalOlapScan olapScan = PlanConstructor.newLogicalOlapScan(1, "tbl", 0);
    LogicalProject<LogicalOlapScan> project = new LogicalProject<>(ImmutableList.of(olapScan.getOutput().get(0)), olapScan);
