    PlanChecker.from(context).applyImplementation(storageLayerAggregateWithProject()).matches(logicalAggregate(logicalProject(physicalStorageLayerAggregate().when(agg -> agg.getAggOp() == PushDownAggOp.MIN_MAX))));
    // count
    aggregate = new LogicalAggregate<>(Collections.emptyList(), ImmutableList.of(new Alias(new Count(project.getOutput().get(0)), "count")), true, Optional.empty(), project);
    context = MemoTestUtils.createCascadesContext(aggregate);
    PlanChecker.from(context).applyImplementation(storageLayerAggregateWithProject()).matches(logicalAggregate(logicalProject(physicalStorageLayerAggregate().when(agg -> agg.getAggOp() == PushDownAggOp.COUNT))));
