     *               scan(student)
     */
@Test
public void pushDownPredicateTwoFilterTest() {
    Slot gender = scan.getOutput().get(1);
    NamedExpression nameMax = new Alias(new Max(scan.getOutput().get(2)), "nameMax");
    Expression filterPredicate = ExpressionUtils.and(new GreaterThan(gender, Literal.of(1)), new LessThanEqual(new Add(gender, Literal.of(10)), Literal.of(100)), new EqualTo(nameMax.toSlot(), Literal.of("abc")));
    LogicalPlan plan = new LogicalPlanBuilder(scan).aggGroupUsingIndex(ImmutableList.of(3, 1), ImmutableList.of(scan.getOutput().get(1), scan.getOutput().get(3), nameMax)).filter(filterPredicate).project(ImmutableList.of(0)).build();
    PlanChecker.from(MemoTestUtils.createConnectContext(), plan).applyTopDown(new PushDownFilterThroughAggregation()).printlnTree().matches(logicalProject(logicalFilter(logicalAggregate(logicalFilter(logicalOlapScan()).when(filter -> ImmutableList.copyOf(filter.getConjuncts()).get(0) instanceof GreaterThan && ImmutableList.copyOf(filter.getConjuncts()).get(1) instanceof LessThanEqual))).when(filter -> ImmutableList.copyOf(filter.getConjuncts()).get(0) instanceof EqualTo)));
}

@Test
public void pushDownPredicateGroupWithRepeatTest() {
    Slot id = scan.getOutput().get(0);
    Slot gender = scan.getOutput().get(1);
    Slot name = scan.getOutput().get(2);
    LogicalRepeat repeatPlan = new LogicalRepeat<>(ImmutableList.of(ImmutableList.of(id, gender), ImmutableList.of(id)), ImmutableList.of(id, gender, name), scan);
    NamedExpression nameMax = new Alias(new Max(name), "nameMax");
    final Expression filterPredicateId = new GreaterThan(id, Literal.of(1));
    LogicalPlan plan = new LogicalPlanBuilder(repeatPlan).aggGroupUsingIndexAndSourceRepeat(ImmutableList.of(0, 1), ImmutableList.of(id, gender, nameMax), Optional.of(repeatPlan)).filter(filterPredicateId).project(ImmutableList.of(0)).build();
    PlanChecker.from(MemoTestUtils.createConnectContext(), plan).applyTopDown(new PushDownFilterThroughAggregation()).printlnTree().matches(logicalProject(logicalAggregate(logicalFilter(logicalRepeat()).when(filter -> filter.getConjuncts().equals(ImmutableSet.of(filterPredicateId))))));
    repeatPlan = new LogicalRepeat<>(ImmutableList.of(ImmutableList.of(id, gender), ImmutableList.of(gender)), ImmutableList.of(id, gender, name), scan);
    plan = new LogicalPlanBuilder(repeatPlan).aggGroupUsingIndexAndSourceRepeat(ImmutableList.of(0, 1), ImmutableList.of(id, gender, nameMax), Optional.of(repeatPlan)).filter(filterPredicateId).project(ImmutableList.of(0)).build();
    PlanChecker.from(MemoTestUtils.createConnectContext(), plan).applyTopDown(new PushDownFilterThroughAggregation()).printlnTree().matches(logicalProject(logicalFilter(logicalAggregate(logicalRepeat())).when(filter -> filter.getConjuncts().equals(ImmutableSet.of(filterPredicateId)))));
}

