@Test
void pushDownFilterThroughWindowTest() {
    ConnectContext context = MemoTestUtils.createConnectContext();
    NamedExpression age = scan.getOutput().get(3).toSlot();
    List<Expression> partitionKeyList = ImmutableList.of(age);
    WindowFrame windowFrame = new WindowFrame(WindowFrame.FrameUnitsType.ROWS, WindowFrame.FrameBoundary.newPrecedingBoundary(), WindowFrame.FrameBoundary.newCurrentRowBoundary());
    WindowExpression window1 = new WindowExpression(new RowNumber(), partitionKeyList, Lists.newArrayList(), windowFrame);
    Alias windowAlias1 = new Alias(window1, window1.toSql());
    List<NamedExpression> expressions = Lists.newArrayList(windowAlias1);
    LogicalWindow<LogicalOlapScan> window = new LogicalWindow<>(expressions, scan);
    Expression filterPredicate = new EqualTo(age, Literal.of(100));
    LogicalPlan plan = new LogicalPlanBuilder(window).filter(filterPredicate).project(ImmutableList.of(0)).build();
    PlanChecker.from(context, plan).applyTopDown(new PushDownFilterThroughWindow()).matches(logicalProject(logicalWindow(logicalFilter(logicalOlapScan()).when(filter -> {
        if (filter.getConjuncts().size() != 1) {
            return false;
        }
        Expression conj = filter.getConjuncts().iterator().next();
        if (!(conj instanceof EqualTo)) {
            return false;
        }
        EqualTo eq = (EqualTo) conj;
        return eq.left().equals(age);
    }))));
}

