        List<PlanFragment> fragments = planner.getFragments();
        Map<String, OlapScanNode> nameToScan = fragments.stream().flatMap(fragment -> {
            Set<OlapScanNode> scans = Sets.newHashSet();
            fragment.getPlanRoot().collect(OlapScanNode.class, scans);
            return scans.stream();
        }).collect(Collectors.toMap(olapScanNode -> olapScanNode.getOlapTable().getName(), Function.identity(), // plan among fragments has duplicate elements.
        (s1, s2) -> s1));
        // limit is push down to left scan of `t1`.
        Assertions.assertEquals(2, nameToScan.size());
        Assertions.assertEquals(5, nameToScan.get("t1").getLimit());
    });
}

