    List<OrderExpression> orderKeyList = ImmutableList.of(new OrderExpression(new OrderKey(grade, true, true)));
    WindowFrame windowFrame = new WindowFrame(WindowFrame.FrameUnitsType.ROWS, WindowFrame.FrameBoundary.newPrecedingBoundary(), WindowFrame.FrameBoundary.newCurrentRowBoundary());
    WindowExpression window1 = new WindowExpression(new RowNumber(), partitionKeyList, orderKeyList, windowFrame);
