    LogicalPlan plan = new LogicalPlanBuilder(window).limit(100).build();
    PlanChecker.from(context, plan).rewrite().matches(logicalLimit(logicalWindow(logicalPartitionTopN(logicalOlapScan()).when(logicalPartitionTopN -> {
        WindowFuncType funName = logicalPartitionTopN.getFunction();
