    ImmutableList<LogicalPlan> plans = ImmutableList.of(new LogicalPlanBuilder(scan1).joinEmptyOn(scan2, JoinType.CROSS_JOIN).joinEmptyOn(scan3, JoinType.CROSS_JOIN).filter(new EqualTo(scan1.getOutput().get(0), scan3.getOutput().get(0))).build(), new LogicalPlanBuilder(scan1).joinEmptyOn(scan2, JoinType.CROSS_JOIN).joinEmptyOn(scan3, JoinType.CROSS_JOIN).filter(new EqualTo(scan1.getOutput().get(0), scan2.getOutput().get(0))).build());
    for (LogicalPlan plan : plans) {
        ConnectContext connectContext = MemoTestUtils.createConnectContext();
        connectContext.getSessionVariable().setDisableNereidsRules("PRUNE_EMPTY_PARTITION");
        PlanChecker.from(connectContext, plan).applyBottomUp(new ReorderJoin()).matchesFromRoot(logicalJoin(logicalJoin().whenNot(join -> join.getJoinType().isCrossJoin()), leafPlan()).when(join -> join.getJoinType().isCrossJoin()));
    }
}

/*
     *                                  join
     *      crossjoin                   /  \
     *       /     \                  join  D
     * innerjoin  innerjoin  ──►      /  \
     *   /   \     /   \            join  C
     *  A     B   C     D           /  \
     *                             A    B
     */
@Test
public void testInnerOrCrossJoin() {
    LogicalPlan leftJoin = new LogicalPlanBuilder(scan1).join(scan2, JoinType.INNER_JOIN, Pair.of(0, 0)).build();
    LogicalPlan rightJoin = new LogicalPlanBuilder(scan3).join(scan4, JoinType.INNER_JOIN, Pair.of(0, 0)).build();
    LogicalPlan plan = new LogicalPlanBuilder(leftJoin).joinEmptyOn(rightJoin, JoinType.CROSS_JOIN).filter(new EqualTo(scan1.getOutput().get(0), scan3.getOutput().get(0))).build();
    ConnectContext connectContext = MemoTestUtils.createConnectContext();
    connectContext.getSessionVariable().setDisableNereidsRules("PRUNE_EMPTY_PARTITION");
    PlanChecker.from(connectContext, plan).applyBottomUp(new ReorderJoin()).matchesFromRoot(logicalJoin(logicalJoin(logicalJoin().whenNot(join -> join.getJoinType().isCrossJoin()), leafPlan()).whenNot(join -> join.getJoinType().isCrossJoin()), leafPlan()).whenNot(join -> join.getJoinType().isCrossJoin())).printlnTree();
}

