@Test
void pushLeft() {
    /*-
         *     topSemiJoin                    project
         *      /     \                         |
         *   project   C                    newTopJoin
         *      |            ->            /         \
         *  bottomJoin            newBottomSemiJoin   B
         *   /    \                    /      \
         *  A      B                  A        C
         */
    LogicalPlan topJoin = new LogicalPlanBuilder(scan1).join(scan2, JoinType.INNER_JOIN, // t1.id = t2.id
    Pair.of(0, 0)).project(ImmutableList.of(0)).join(scan3, JoinType.LEFT_SEMI_JOIN, // t1.id = t3.id
    Pair.of(0, 0)).build();
    PlanChecker.from(MemoTestUtils.createConnectContext(), topJoin).applyTopDown(new TransposeSemiJoinLogicalJoinProject()).matchesFromRoot(logicalProject(innerLogicalJoin(leftSemiLogicalJoin(logicalOlapScan().when(scan -> scan.getTable().getName().equals("t1")), logicalOlapScan().when(scan -> scan.getTable().getName().equals("t3"))), logicalOlapScan().when(scan -> scan.getTable().getName().equals("t2")))));
}

@Test
void pushRight() {
    /*-
         *     topSemiJoin                  project
         *       /     \                       |
         *    project   C                  newTopJoin
         *       |                        /         \
         *  bottomJoin  C     -->       A     newBottomSemiJoin
         *    /    \                              /      \
         *   A      B                             B       C
         */
    LogicalPlan topJoin = new LogicalPlanBuilder(scan1).join(scan2, JoinType.INNER_JOIN, // t1.id = t2.id
    Pair.of(0, 0)).project(// t1.id, t2.id
    ImmutableList.of(0, 2)).join(scan3, JoinType.LEFT_SEMI_JOIN, // t2.id = t3.id
    Pair.of(1, 0)).build();
    PlanChecker.from(MemoTestUtils.createConnectContext(), topJoin).applyTopDown(new TransposeSemiJoinLogicalJoinProject()).matchesFromRoot(logicalProject(logicalJoin(logicalOlapScan().when(scan -> scan.getTable().getName().equals("t1")), leftSemiLogicalJoin(logicalOlapScan().when(scan -> scan.getTable().getName().equals("t2")), logicalOlapScan().when(scan -> scan.getTable().getName().equals("t3"))))));
}

