@Test
public void test1() {
    SlotReference a = new SlotReference("a", IntegerType.INSTANCE);
    Max max = new Max(a);
    Map<Expression, ColumnStatistic> slotToColumnStat = new HashMap<>();
    ColumnStatisticBuilder builder = new ColumnStatisticBuilder().setNdv(500).setAvgSizeByte(4).setNumNulls(0).setMinValue(0).setMaxValue(500);
