@Test
void testLogicalAggregate(@Mocked Plan child) {
    LogicalAggregate<Plan> actual = new LogicalAggregate<>(Lists.newArrayList(), ImmutableList.of(new SlotReference(new ExprId(0), "a", BigIntType.INSTANCE, true, Lists.newArrayList())), child);
    LogicalAggregate<Plan> expected = new LogicalAggregate<>(Lists.newArrayList(), ImmutableList.of(new SlotReference(new ExprId(0), "a", BigIntType.INSTANCE, true, Lists.newArrayList())), child);
    Assertions.assertEquals(expected, actual);
    LogicalAggregate<Plan> unexpected = new LogicalAggregate<>(Lists.newArrayList(), ImmutableList.of(new SlotReference(new ExprId(1), "b", BigIntType.INSTANCE, true, Lists.newArrayList())), child);
    Assertions.assertNotEquals(unexpected, actual);
    unexpected = new LogicalAggregate<>(Lists.newArrayList(), ImmutableList.of(new SlotReference(new ExprId(1), "b", BigIntType.INSTANCE, true, Lists.newArrayList())), false, Optional.empty(), child);
    Assertions.assertNotEquals(unexpected, actual);
    unexpected = new LogicalAggregate<>(Lists.newArrayList(), ImmutableList.of(new SlotReference(new ExprId(1), "b", BigIntType.INSTANCE, true, Lists.newArrayList())), true, Optional.empty(), child);
    Assertions.assertNotEquals(unexpected, actual);
    unexpected = new LogicalAggregate<>(Lists.newArrayList(), ImmutableList.of(new SlotReference(new ExprId(1), "b", BigIntType.INSTANCE, true, Lists.newArrayList())), false, Optional.empty(), child);
    Assertions.assertNotEquals(unexpected, actual);
}

