@Test
public void testCastIfNotSameType() {
    Assertions.assertEquals(new DoubleLiteral(5L), TypeCoercionUtils.castIfNotSameType(new DoubleLiteral(5L), DoubleType.INSTANCE));
    Assertions.assertEquals(new Cast(new DoubleLiteral(5L), BooleanType.INSTANCE), TypeCoercionUtils.castIfNotSameType(new DoubleLiteral(5L), BooleanType.INSTANCE));
    Assertions.assertEquals(new StringLiteral("varchar"), TypeCoercionUtils.castIfNotSameType(new VarcharLiteral("varchar"), StringType.INSTANCE));
    Assertions.assertEquals(new StringLiteral("char"), TypeCoercionUtils.castIfNotSameType(new CharLiteral("char", 4), StringType.INSTANCE));
    Assertions.assertEquals(new CharLiteral("char", 4), TypeCoercionUtils.castIfNotSameType(new CharLiteral("char", 4), VarcharType.createVarcharType(100)));
    Assertions.assertEquals(new StringLiteral("string"), TypeCoercionUtils.castIfNotSameType(new StringLiteral("string"), VarcharType.createVarcharType(100)));
}

@Test
public void testDecimalArithmetic() {
    Multiply multiply = new Multiply(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    Expression expression = TypeCoercionUtils.processBinaryArithmetic(multiply);
    Assertions.assertEquals(expression.child(0), new Cast(multiply.child(0), DecimalV3Type.createDecimalV3Type(9, 3)));
    Divide divide = new Divide(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    expression = TypeCoercionUtils.processBinaryArithmetic(divide);
    Assertions.assertEquals(expression.child(0), new Cast(multiply.child(0), DecimalV3Type.createDecimalV3Type(9, 3)));
    Add add = new Add(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    expression = TypeCoercionUtils.processBinaryArithmetic(add);
    Assertions.assertEquals(expression.child(0), new Cast(multiply.child(0), DecimalV3Type.createDecimalV3Type(10, 3)));
    Subtract sub = new Subtract(new DecimalLiteral(new BigDecimal("987654.321")), new DecimalV3Literal(new BigDecimal("123.45")));
    expression = TypeCoercionUtils.processBinaryArithmetic(sub);
