@Test
public void testExplicitlyBroadcastJoin() throws Exception {
    String sql = "explain select * from db1.tbl1 join [BROADCAST] db1.tbl2 on tbl1.k1 = tbl2.k3";
    StmtExecutor stmtExecutor = new StmtExecutor(ctx, sql);
