            tableA.getId();
            result = 1;
            aggregateInfo.getAggregateExprs();
            result = Lists.newArrayList(tableAColumn2Sum, tableBColumn1Max);
            tableAColumn2Sum.getChildren();
            result = Lists.newArrayList(tableAColumn2);
            tableBColumn1Max.getChildren();
