" + "  `l_tax` decimal(15, 2) NOT NULL COMMENT "",
" + "  `l_returnflag` char(1) NOT NULL COMMENT "",
" + "  `l_linestatus` char(1) NOT NULL COMMENT "",
" + "  `l_shipdate` date NOT NULL COMMENT "",
" + "  `l_commitdate` date NOT NULL COMMENT "",
" + "  `l_receiptdate` date NOT NULL COMMENT "",
" + "  `l_shipinstruct` char(25) NOT NULL COMMENT "",
" + "  `l_shipmode` char(10) NOT NULL COMMENT "",
" + "  `l_comment` varchar(44) NOT NULL COMMENT ""
" + ") ENGINE=OLAP
" + "DUPLICATE KEY(`l_orderkey`)
" + "COMMENT "OLAP"
" + "DISTRIBUTED BY HASH(`l_orderkey`) BUCKETS 2
" + "PROPERTIES (
" + ""replication_num" = "1",
" + ""in_memory" = "false",
" + ""storage_format" = "V2"
" + ");";
    dorisAssert.withTable(createTableSQL);
    createTableSQL = "CREATE TABLE `part` (
" + "  `p_partkey` int(11) NOT NULL COMMENT "",
" + "  `p_name` varchar(55) NOT NULL COMMENT "",
" + "  `p_mfgr` char(25) NOT NULL COMMENT "",
" + "  `p_brand` char(10) NOT NULL COMMENT "",
" + "  `p_type` varchar(25) NOT NULL COMMENT "",
" + "  `p_size` int(11) NOT NULL COMMENT "",
" + "  `p_container` char(10) NOT NULL COMMENT "",
" + "  `p_retailprice` decimal(15, 2) NOT NULL COMMENT "",
" + "  `p_comment` varchar(23) NOT NULL COMMENT ""
" + ") ENGINE=OLAP
" + "DUPLICATE KEY(`p_partkey`)
" + "COMMENT "OLAP"
" + "DISTRIBUTED BY HASH(`p_partkey`) BUCKETS 2
" + "PROPERTIES (
" + ""replication_num" = "1",
" + ""in_memory" = "false",
" + ""storage_format" = "V2"
" + ");";
    dorisAssert.withTable(createTableSQL);
    String query = "select /*+ SET_VAR(enable_nereids_planner=false,enable_fold_constant_by_be=false) */ sum(l_extendedprice* (1 - l_discount)) as revenue " + "from lineitem, part " + "where ( p_partkey = l_partkey and p_brand = 'Brand#11' " + "and p_container in ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG') " + "and l_quantity >= 9 and l_quantity <= 9 + 10 " + "and p_size between 1 and 5 and l_shipmode in ('AIR', 'AIR REG') " + "and l_shipinstruct = 'DELIVER IN PERSON' ) " + "or ( p_partkey = l_partkey and p_brand = 'Brand#21' " + "and p_container in ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK') " + "and l_quantity >= 20 and l_quantity <= 20 + 10 " + "and p_size between 1 and 10 and l_shipmode in ('AIR', 'AIR REG') " + "and l_shipinstruct = 'DELIVER IN PERSON' ) " + "or ( p_partkey = l_partkey and p_brand = 'Brand#32' " + "and p_container in ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG') " + "and l_quantity >= 26 and l_quantity <= 26 + 10 " + "and p_size between 1 and 15 and l_shipmode in ('AIR', 'AIR REG') " + "and l_shipinstruct = 'DELIVER IN PERSON' )";
    String planString = dorisAssert.query(query).explainQuery();
    Assert.assertTrue(planString.contains("HASH JOIN"));
    Assert.assertTrue(planString.contains("`l_partkey` = `p_partkey`"));
    Assert.assertTrue(planString.contains("`l_shipmode` IN ('AIR', 'AIR REG')"));
    Assert.assertTrue(planString.contains("`l_shipinstruct` = 'DELIVER IN PERSON'"));
    Assert.assertTrue(planString.contains("(`l_quantity` >= 9.00) AND (`l_quantity` <= 19.00) " + "OR (`l_quantity` >= 20.00) AND (`l_quantity` <= 36.00)"));
    Assert.assertTrue(planString.contains("`p_size` >= 1"));
    Assert.assertTrue(planString.contains("`p_brand` IN ('Brand#11', 'Brand#21', 'Brand#32')"));
    Assert.assertTrue(planString.contains("`p_size` <= 15"));
    Assert.assertTrue(planString.contains("`p_container` IN ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG', 'MED BAG', " + "'MED BOX', 'MED PKG', 'MED PACK', 'LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')"));
}

