@Test
public void timeNowTest() throws AnalysisException {
    String curTimeString = FEFunctions.curTime().toSqlImpl().replace("'", "");
    String currentTimestampString = FEFunctions.currentTimestamp().toSqlImpl().replace("'", "");
    ZonedDateTime zonedDateTime = ZonedDateTime.now(TimeUtils.getTimeZone().toZoneId());
    DateTimeFormatter formatter = null;
    if (Config.enable_date_conversion) {
        formatter = new DateTimeFormatterBuilder().appendPattern("uuuu-MM-dd HH:mm:ss").appendFraction(ChronoField.MICRO_OF_SECOND, 0, 6, true).toFormatter();
    } else {
        formatter = new DateTimeFormatterBuilder().appendPattern("uuuu-MM-dd HH:mm:ss").toFormatter();
    }
    Assert.assertTrue(formatter.format(zonedDateTime).compareTo(currentTimestampString) >= 0);
    String nowTimeString = formatter.format(zonedDateTime).substring(formatter.format(zonedDateTime).indexOf(" ") + 1);
    Assert.assertTrue(nowTimeString.compareTo(curTimeString) >= 0);
}

@Test
public void datePlusAndSubTest() throws AnalysisException {
    DateLiteral dateLiteral = new DateLiteral("2019-11-11 00:00:00", Type.DATETIME);
    Assert.assertEquals(new DateLiteral("2020-11-11 00:00:00", Type.DATETIME), FEFunctions.yearsAdd(dateLiteral, new IntLiteral(1)));
    Assert.assertEquals(new DateLiteral("2018-11-11 00:00:00", Type.DATETIME), FEFunctions.yearsSub(dateLiteral, new IntLiteral(1)));
    Assert.assertEquals(new DateLiteral("2019-12-11 00:00:00", Type.DATETIME), FEFunctions.monthsAdd(dateLiteral, new IntLiteral(1)));
    Assert.assertEquals(new DateLiteral("2019-10-11 00:00:00", Type.DATETIME), FEFunctions.monthsSub(dateLiteral, new IntLiteral(1)));
    Assert.assertEquals(new DateLiteral("2019-11-12 00:00:00", Type.DATETIME), FEFunctions.daysAdd(dateLiteral, new IntLiteral(1)));
    Assert.assertEquals(new DateLiteral("2019-11-10 00:00:00", Type.DATETIME), FEFunctions.daysSub(dateLiteral, new IntLiteral(1)));
    Assert.assertEquals(new DateLiteral("2019-11-11 01:00:00", Type.DATETIME), FEFunctions.hoursAdd(dateLiteral, new IntLiteral(1)));
    Assert.assertEquals(new DateLiteral("2019-11-10 23:00:00", Type.DATETIME), FEFunctions.hoursSub(dateLiteral, new IntLiteral(1)));
    Assert.assertEquals(new DateLiteral("2019-11-11 00:01:00", Type.DATETIME), FEFunctions.minutesAdd(dateLiteral, new IntLiteral(1)));
    Assert.assertEquals(new DateLiteral("2019-11-10 23:59:00", Type.DATETIME), FEFunctions.minutesSub(dateLiteral, new IntLiteral(1)));
    Assert.assertEquals(new DateLiteral("2019-11-11 00:00:01", Type.DATETIME), FEFunctions.secondsAdd(dateLiteral, new IntLiteral(1)));
    Assert.assertEquals(new DateLiteral("2019-11-10 23:59:59", Type.DATETIME), FEFunctions.secondsSub(dateLiteral, new IntLiteral(1)));
}

