/**
 * txn -> TabletQuorumFailedException
 *   sub_txn1: table1, replica: 1, 2 success
 *   sub_txn2: table1, replica: 1, 3 success
 *   sub_txn3: table1, replica: 2, 3 success
 */
@Test
public void testCommitTransactionWithSubTxnAndReplicaFailed() throws UserException {
    FakeEnv.setEnv(masterEnv);
    Table table1 = masterEnv.getInternalCatalog().getDbOrMetaException(CatalogTestUtil.testDbId1).getTableOrMetaException(CatalogTestUtil.testTableId1);
    // check partition version
    checkVersion(table1, CatalogTestUtil.testPartition1, CatalogTestUtil.testIndexId1, CatalogTestUtil.testTabletId1, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 1, CatalogTestUtil.testStartVersion);
    // begin txn
    long transactionId = masterTransMgr.beginTransaction(CatalogTestUtil.testDbId1, Lists.newArrayList(CatalogTestUtil.testTableId1), CatalogTestUtil.testTxnLabel1, transactionSource, LoadJobSourceType.FRONTEND, Config.stream_load_default_timeout_second);
    TransactionState transactionState = fakeEditLog.getTransaction(transactionId);
    // commit table1 with 1, 2 success; table2 with all success; table1 with all success
    List<SubTransactionInfo> subTransactionInfos = Lists.newArrayList(new SubTransactionInfo(table1, CatalogTestUtil.testTabletId1, Lists.newArrayList(CatalogTestUtil.testBackendId1, CatalogTestUtil.testBackendId2)), new SubTransactionInfo(table1, CatalogTestUtil.testTabletId1, Lists.newArrayList(CatalogTestUtil.testBackendId1, CatalogTestUtil.testBackendId3)), new SubTransactionInfo(table1, CatalogTestUtil.testTabletId1, Lists.newArrayList(CatalogTestUtil.testBackendId2, CatalogTestUtil.testBackendId2)));
    List<SubTransactionState> subTransactionStates = generateSubTransactionStates(transactionState, subTransactionInfos);
    // commit txn
    try {
        masterTransMgr.commitTransaction(CatalogTestUtil.testDbId1, Lists.newArrayList(table1), transactionId, subTransactionStates, 300000);
    } catch (TabletQuorumFailedException e) {
        // check status is prepare, because the commit failed
        Assert.assertEquals(TransactionStatus.PREPARE, transactionState.getTransactionStatus());
    }
}

@Test
public void testFinishTransactionWithSubTransaction() throws UserException {
    FakeEnv.setEnv(masterEnv);
    OlapTable table1 = (OlapTable) (masterEnv.getInternalCatalog().getDbOrMetaException(CatalogTestUtil.testDbId1).getTableOrMetaException(CatalogTestUtil.testTableId1));
    OlapTable table2 = (OlapTable) (masterEnv.getInternalCatalog().getDbOrMetaException(CatalogTestUtil.testDbId1).getTableOrMetaException(CatalogTestUtil.testTableId2));
    // check partition version
    checkVersion(table1, CatalogTestUtil.testPartition1, CatalogTestUtil.testIndexId1, CatalogTestUtil.testTabletId1, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 1, CatalogTestUtil.testStartVersion);
    checkVersion(table2, CatalogTestUtil.testPartition2, CatalogTestUtil.testIndexId2, CatalogTestUtil.testTabletId2, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 1, CatalogTestUtil.testStartVersion);
    // begin txn
    long transactionId = masterTransMgr.beginTransaction(CatalogTestUtil.testDbId1, Lists.newArrayList(CatalogTestUtil.testTableId1), CatalogTestUtil.testTxnLabel1, transactionSource, LoadJobSourceType.FRONTEND, Config.stream_load_default_timeout_second);
    TransactionState transactionState = fakeEditLog.getTransaction(transactionId);
    // commit table1, table2, table1
    List<SubTransactionInfo> subTransactionInfos = Lists.newArrayList(new SubTransactionInfo(table1, CatalogTestUtil.testTabletId1, allBackends), new SubTransactionInfo(table2, CatalogTestUtil.testTabletId2, allBackends), new SubTransactionInfo(table1, CatalogTestUtil.testTabletId1, allBackends));
    List<SubTransactionState> subTransactionStates = generateSubTransactionStates(transactionState, subTransactionInfos);
    // commit txn
    transactionState.setSubTxnIds(subTransactionStates.stream().map(SubTransactionState::getSubTransactionId).collect(Collectors.toList()));
    masterTransMgr.commitTransaction(CatalogTestUtil.testDbId1, Lists.newArrayList(table1, table2), transactionId, subTransactionStates, 300000);
    // check status is committed
    Assert.assertEquals(TransactionStatus.COMMITTED, transactionState.getTransactionStatus());
    // check partition version
    checkVersion(table1, CatalogTestUtil.testPartition1, CatalogTestUtil.testIndexId1, CatalogTestUtil.testTabletId1, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 3, CatalogTestUtil.testStartVersion);
    checkVersion(table2, CatalogTestUtil.testPartition2, CatalogTestUtil.testIndexId2, CatalogTestUtil.testTabletId2, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 2, CatalogTestUtil.testStartVersion);
    // slave replay new state and compare catalog
    FakeEnv.setEnv(slaveEnv);
    slaveTransMgr.replayUpsertTransactionState(transactionState);
    Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
    checkTableVersion(table1, 1, 2);
    checkTableVersion(table2, 1, 2);
    // finish transaction
    Map<String, Map<Long, Long>> keyToSuccessTablets = new HashMap<>();
    DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, allBackends, subTransactionStates.get(0).getSubTransactionId(), CatalogTestUtil.testTabletId1, 14);
    DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, allBackends, subTransactionStates.get(1).getSubTransactionId(), CatalogTestUtil.testTabletId2, 13);
    DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, Lists.newArrayList(CatalogTestUtil.testBackendId2, CatalogTestUtil.testBackendId3), subTransactionStates.get(2).getSubTransactionId(), CatalogTestUtil.testTabletId1, 15);
    DatabaseTransactionMgrTest.setTransactionFinishPublish(transactionState, allBackends, keyToSuccessTablets);
    Map<Long, Long> partitionVisibleVersions = Maps.newHashMap();
    Map<Long, Set<Long>> backendPartitions = Maps.newHashMap();
    masterTransMgr.finishTransaction(CatalogTestUtil.testDbId1, transactionId, partitionVisibleVersions, backendPartitions);
    Assert.assertEquals(TransactionStatus.VISIBLE, transactionState.getTransactionStatus());
    // check table1 partition version
    Partition testPartition = masterEnv.getInternalCatalog().getDbOrMetaException(CatalogTestUtil.testDbId1).getTableOrMetaException(CatalogTestUtil.testTableId1).getPartition(CatalogTestUtil.testPartition1);
    Assert.assertEquals(CatalogTestUtil.testStartVersion + 2, testPartition.getVisibleVersion());
    Assert.assertEquals(CatalogTestUtil.testStartVersion + 3, testPartition.getNextVersion());
    // check table1 replica version, table1 has 3 replicas
    Tablet tablet = testPartition.getIndex(CatalogTestUtil.testIndexId1).getTablet(CatalogTestUtil.testTabletId1);
    for (Replica replica : tablet.getReplicas()) {
        if (replica.getId() == CatalogTestUtil.testReplicaId1) {
            // TODO replica version is [CatalogTestUtil.testStartVersion + 1] is an improvement
            Assert.assertEquals(CatalogTestUtil.testStartVersion, replica.getVersion());
        } else {
            Assert.assertEquals(CatalogTestUtil.testStartVersion + 2, replica.getVersion());
        }
    }
    // check table2 version, table2 has 1 replicas
    checkVersion(table2, CatalogTestUtil.testPartition2, CatalogTestUtil.testIndexId2, CatalogTestUtil.testTabletId2, CatalogTestUtil.testStartVersion + 1, CatalogTestUtil.testStartVersion + 2, CatalogTestUtil.testStartVersion + 1);
    checkTableVersion(table1, 2, 3);
    checkTableVersion(table2, 2, 3);
    // slave replay new state and compare catalog
    slaveTransMgr.replayUpsertTransactionState(transactionState);
    Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
}

/**
 * commit with only two replicas
 * txn1 -> commit and publish success
 *   sub_txn1: table1, replica: 1, 2 success; replica1 publish failed and then succeed
 *   sub_txn2: table2, all replicas success
 *   sub_txn3: table1, all replicas success
 */
@Test
public void testFinishTransactionWithSubTransactionAndOneFailed() throws UserException {
    FakeEnv.setEnv(masterEnv);
    // table1
    OlapTable table1 = (OlapTable) (masterEnv.getInternalCatalog().getDbOrMetaException(CatalogTestUtil.testDbId1).getTableOrMetaException(CatalogTestUtil.testTableId1));
    Partition partition1 = table1.getPartition(CatalogTestUtil.testPartition1);
    Tablet tablet1 = partition1.getIndex(CatalogTestUtil.testIndexId1).getTablet(CatalogTestUtil.testTabletId1);
    Replica replica11 = tablet1.getReplicaById(CatalogTestUtil.testReplicaId1);
    Replica replica12 = tablet1.getReplicaById(CatalogTestUtil.testReplicaId2);
    Replica replica13 = tablet1.getReplicaById(CatalogTestUtil.testReplicaId3);
    // table2
    OlapTable table2 = (OlapTable) (masterEnv.getInternalCatalog().getDbOrMetaException(CatalogTestUtil.testDbId1).getTableOrMetaException(CatalogTestUtil.testTableId2));
    Partition partition2 = table2.getPartition(CatalogTestUtil.testPartition2);
    Tablet tablet2 = partition2.getIndex(CatalogTestUtil.testIndexId2).getTablet(CatalogTestUtil.testTabletId2);
    Replica replica21 = tablet2.getReplicaById(CatalogTestUtil.testReplicaId4);
    // txn1
    if (true) {
        // begin txn
        long transactionId = masterTransMgr.beginTransaction(CatalogTestUtil.testDbId1, Lists.newArrayList(CatalogTestUtil.testTableId1), CatalogTestUtil.testTxnLabel1, transactionSource, LoadJobSourceType.FRONTEND, Config.stream_load_default_timeout_second);
        TransactionState transactionState = fakeEditLog.getTransaction(transactionId);
        // commit table1 with 1, 2 success; table2 with all success; table1 with all success
        List<SubTransactionInfo> subTransactionInfos = Lists.newArrayList(new SubTransactionInfo(table1, CatalogTestUtil.testTabletId1, Lists.newArrayList(CatalogTestUtil.testBackendId1, CatalogTestUtil.testBackendId2)), new SubTransactionInfo(table2, CatalogTestUtil.testTabletId2, allBackends), new SubTransactionInfo(table1, CatalogTestUtil.testTabletId1, allBackends));
        List<SubTransactionState> subTransactionStates = generateSubTransactionStates(transactionState, subTransactionInfos);
        // commit txn
        transactionState.setSubTxnIds(subTransactionStates.stream().map(SubTransactionState::getSubTransactionId).collect(Collectors.toList()));
        masterTransMgr.commitTransaction(CatalogTestUtil.testDbId1, Lists.newArrayList(table1, table2), transactionId, subTransactionStates, 300000);
        // check status is committed
        Assert.assertEquals(TransactionStatus.COMMITTED, transactionState.getTransactionStatus());
        // check partition version
        checkVersion(table1, CatalogTestUtil.testPartition1, CatalogTestUtil.testIndexId1, CatalogTestUtil.testTabletId1, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 3, CatalogTestUtil.testStartVersion);
        checkVersion(table2, CatalogTestUtil.testPartition2, CatalogTestUtil.testIndexId2, CatalogTestUtil.testTabletId2, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 2, CatalogTestUtil.testStartVersion);
        // check table1 replica3 last success and failed version
        checkReplicaVersion(replica13, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 1);
        // follower catalog replay the transaction
        transactionState = fakeEditLog.getTransaction(transactionId);
        FakeEnv.setEnv(slaveEnv);
        slaveTransMgr.replayUpsertTransactionState(transactionState);
        Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
        // master finish the transaction failed
        FakeEnv.setEnv(masterEnv);
        Map<String, Map<Long, Long>> keyToSuccessTablets = new HashMap<>();
        // backend2, backend3 publish failed
        DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, Lists.newArrayList(CatalogTestUtil.testBackendId1), subTransactionStates.get(0).getSubTransactionId(), CatalogTestUtil.testTabletId1, 14);
        DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, allBackends, subTransactionStates.get(1).getSubTransactionId(), CatalogTestUtil.testTabletId2, 13);
        DatabaseTransactionMgrTest.setSuccessTablet(keyToSuccessTablets, allBackends, subTransactionStates.get(2).getSubTransactionId(), CatalogTestUtil.testTabletId1, 15);
        DatabaseTransactionMgrTest.setTransactionFinishPublish(transactionState, allBackends, keyToSuccessTablets);
        LOG.info("publish tasks: {}", transactionState.getPublishVersionTasks());
        // finish transaction
        Map<Long, Long> partitionVisibleVersions = Maps.newHashMap();
        Map<Long, Set<Long>> backendPartitions = Maps.newHashMap();
        masterTransMgr.finishTransaction(CatalogTestUtil.testDbId1, transactionId, partitionVisibleVersions, backendPartitions);
        Assert.assertEquals(TransactionStatus.COMMITTED, transactionState.getTransactionStatus());
        // because after calling `finishTransaction`, the txn state is COMMITTED, not VISIBLE,
        // so all replicas' version are not changed.
        checkReplicaVersion(replica11, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, -1);
        checkReplicaVersion(replica12, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, -1);
        checkReplicaVersion(replica13, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 1);
        checkReplicaVersion(replica21, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, -1);
        checkTableVersion(table1, 1, 2);
        checkTableVersion(table2, 1, 2);
        // backend2 publish success (tabletId to version map)
        List<PublishVersionTask> publishVersionTasks = transactionState.getPublishVersionTasks().get(CatalogTestUtil.testBackendId2).stream().filter(t -> t.getTransactionId() == subTransactionStates.get(0).getSubTransactionId()).collect(Collectors.toList());
        Assert.assertEquals(1, publishVersionTasks.size());
        PublishVersionTask publishVersionTask = publishVersionTasks.get(0);
        publishVersionTask.setSuccTablets(ImmutableMap.of(CatalogTestUtil.testTabletId1, 100L));
        masterTransMgr.finishTransaction(CatalogTestUtil.testDbId1, transactionId, partitionVisibleVersions, backendPartitions);
        Assert.assertEquals(TransactionStatus.VISIBLE, transactionState.getTransactionStatus());
        checkReplicaVersion(replica11, CatalogTestUtil.testStartVersion + 2, CatalogTestUtil.testStartVersion + 2, -1);
        checkReplicaVersion(replica12, CatalogTestUtil.testStartVersion + 2, CatalogTestUtil.testStartVersion + 2, -1);
        checkReplicaVersion(replica13, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion, CatalogTestUtil.testStartVersion + 1);
        checkReplicaVersion(replica21, CatalogTestUtil.testStartVersion + 1, CatalogTestUtil.testStartVersion + 1, -1);
        checkTableVersion(table1, 2, 3);
        checkTableVersion(table2, 2, 3);
        // follower catalog replay the transaction
        transactionState = fakeEditLog.getTransaction(transactionId);
        FakeEnv.setEnv(slaveEnv);
        slaveTransMgr.replayUpsertTransactionState(transactionState);
        Assert.assertTrue(CatalogTestUtil.compareCatalog(masterEnv, slaveEnv));
    }
}

