@Test
public void testCheckConfigWithBitmapDictColumns() {
    SparkEtlJob job = Deencapsulation.newInstance(SparkEtlJob.class, "hdfs://127.0.0.1:10000/jobconfig.json");
    EtlTable table = etlJobConfig.tables.get(tableId);
    table.indexes.get(0).columns.add(new EtlColumn("v2", "BITMAP", false, false, "BITMAP_UNION", "0", 0, 0, 0));
    EtlFileGroup fileGroup = table.fileGroups.get(0);
    fileGroup.sourceType = EtlJobConfig.SourceType.HIVE;
    fileGroup.columnMappings.put("v2", new EtlColumnMapping("bitmap_dict", Lists.newArrayList("v2")));
    Deencapsulation.setField(job, "etlJobConfig", etlJobConfig);
    Deencapsulation.invoke(job, "checkConfig");
    // check hive source
    Set<Long> hiveSourceTables = Deencapsulation.getField(job, "hiveSourceTables");
    Assert.assertTrue(hiveSourceTables.contains(tableId));
    // check bitmap dict columns has v2
    Map<Long, Set<String>> tableToBitmapDictColumns = Deencapsulation.getField(job, "tableToBitmapDictColumns");
    Assert.assertTrue(tableToBitmapDictColumns.containsKey(tableId));
    Assert.assertTrue(tableToBitmapDictColumns.get(tableId).contains("v2"));
    // check remove v2 bitmap_dict func mapping from file group column mappings
    Assert.assertFalse(table.fileGroups.get(0).columnMappings.containsKey("v2"));
}

@Test
public void testCommonFnTransformers() {
    // test json functions
    testFunction("SELECT json_extract('{\"c1\": 1}', '$.c1') as b FROM t", "SELECT get_json_object('{\"c1\": 1}', '$.c1') as b FROM t", "json_extract('{\"c1\": 1}', '$.c1')");
    testFunction("SELECT json_extract(c1, '$.c1') as b FROM t", "SELECT get_json_object(c1, '$.c1') as b FROM t", "json_extract('c1, '$.c1')");
    // test string functions
    testFunction("SELECT str_to_date('2023-12-16', 'yyyy-MM-dd') as b FROM t", "SELECT to_date('2023-12-16', 'yyyy-MM-dd') as b FROM t", "str_to_date('2023-12-16', 'yyyy-MM-dd')");
    testFunction("SELECT str_to_date(c1, 'yyyy-MM-dd') as b FROM t", "SELECT to_date(c1, 'yyyy-MM-dd') as b FROM t", "str_to_date('c1, 'yyyy-MM-dd')");
    testFunction("SELECT date_trunc('2023-12-16', 'YEAR') as a FROM t", "SELECT trunc('2023-12-16', 'YEAR') as a FROM t", "date_trunc('2023-12-16', 'YEAR')");
    testFunction("SELECT date_trunc(c1, 'YEAR') as a FROM t", "SELECT trunc(c1, 'YEAR') as a FROM t", "date_trunc('c1, 'YEAR')");
    testFunction("SELECT date_trunc('2023-12-16', 'YEAR') as a FROM t", "SELECT trunc('2023-12-16', 'YY') as a FROM t", "date_trunc('2023-12-16', 'YEAR')");
    testFunction("SELECT date_trunc(c1, 'YEAR') as a FROM t", "SELECT trunc(c1, 'YY') as a FROM t", "date_trunc('c1, 'YEAR')");
    testFunction("SELECT date_trunc('2023-12-16', 'MONTH') as a FROM t", "SELECT trunc('2023-12-16', 'MON') as a FROM t", "date_trunc('2023-12-16', 'MONTH')");
    testFunction("SELECT date_trunc(c1, 'MONTH') as a FROM t", "SELECT trunc(c1, 'MON') as a FROM t", "date_trunc('c1, 'MONTH')");
    // test numeric functions
    testFunction("SELECT avg(c1) as a from t", "SELECT mean(c1) as a from t", "avg('c1)");
}

@Test
public void testParseCast1() {
    // doris parser will throw a ParseException when derived table does not have alias
    String sql1 = "select * from (select * from t1);";
    NereidsParser nereidsParser = new NereidsParser();
    Assertions.assertThrows(ParseException.class, () -> nereidsParser.parseSQL(sql1), "Every derived table must have its own alias");
    // test parse with spark-sql dialect
    LogicalPlan dialectLogicalPlan = nereidsParser.parseSingle(sql1, new SparkSql3LogicalPlanBuilder());
    Assertions.assertTrue(dialectLogicalPlan instanceof UnboundResultSink);
}

@Test
public void testStringFnTransform() {
    ParserContext parserContext = new ParserContext(Dialect.TRINO);
    NereidsParser nereidsParser = new NereidsParser();
    String sql = "SELECT ascii('a') as b FROM t";
    LogicalPlan logicalPlan = nereidsParser.parseSingle(sql);
    String dialectSql = "SELECT codepoint('a') as b FROM t";
    LogicalPlan dialectLogicalPlan = TrinoParser.parseSingle(dialectSql, parserContext);
